"use client";

import { ReactFlowProvider, type Connection } from "@xyflow/react";
import clsx from "clsx";
import { AlertTriangle, Info, X, XCircle } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { ArchitectureCanvas } from "@/components/ArchitectureCanvas";
import type { NodeActions } from "@/components/CustomNode";
import { ImportDialog } from "@/components/ImportDialog";
import { InspectorPanel } from "@/components/InspectorPanel";
import { CUSTOM_UPLOAD_OPTION, TopNav } from "@/components/TopNav";
import { useWorkspace, type Notice } from "@/hooks/useWorkspace";
import { fetchEngine, requestImpact, requestRepoFromFiles, requestRepoFromGithub, requestScaffold, requestStory } from "@/lib/apiClient";
import { commitsFromGitLog } from "@/lib/engines/story";
import { kebabCase } from "@/lib/engines/localScaffold";
import { findSample, SAMPLE_PROMPTS, SAMPLE_REPOSITORIES } from "@/lib/mockData";
import { exportCodebase, readUpload } from "@/lib/portability";
import type { ArchitectureGraph, ArchNode, EngineKind, NodeKind } from "@/lib/types";
import { buildRenderGraph } from "@/lib/viewModel";

const STORY_STEP_MS = 2600;
const DRAFT_VERTICAL_GAP_PX = 200;

const NOTICE_STYLE: Record<Notice["tone"], { box: string; icon: typeof Info }> = {
  info: { box: "border-sky-500/30 bg-sky-950/80 text-sky-100", icon: Info },
  warning: { box: "border-amber-500/30 bg-amber-950/80 text-amber-100", icon: AlertTriangle },
  error: { box: "border-red-500/30 bg-red-950/80 text-red-100", icon: XCircle },
};

const errorMessage = (error: unknown) => (error instanceof Error ? error.message : String(error));

export default function Page() {
  const [state, dispatch] = useWorkspace();
  const { graph } = state;
  const [engine, setEngine] = useState<{ engine: EngineKind; model: string | null } | null>(null);
  const [importedGraph, setImportedGraph] = useState<ArchitectureGraph | null>(null);
  const [importState, setImportState] = useState<{ open: boolean; busy: boolean; error: string | null }>({ open: false, busy: false, error: null });
  const [isExporting, setIsExporting] = useState(false);

  // Async results are discarded if the user switched repositories while waiting.
  const graphIdRef = useRef(graph.id);
  graphIdRef.current = graph.id;
  const graphRef = useRef(graph);
  graphRef.current = graph;

  const notify = useCallback((notice: Notice | null) => dispatch({ type: "notify", notice }), [dispatch]);

  useEffect(() => {
    void fetchEngine().then(setEngine);
  }, []);

  /* ---------- Story playback ---------- */
  const { isPlaying, index: storyIndex } = state.story;
  useEffect(() => {
    if (!isPlaying) return;
    if (storyIndex >= graph.commits.length - 1) {
      dispatch({ type: "setStoryPlaying", isPlaying: false });
      return;
    }
    const timer = setTimeout(() => dispatch({ type: "setStoryIndex", index: storyIndex + 1 }), STORY_STEP_MS);
    return () => clearTimeout(timer);
  }, [isPlaying, storyIndex, graph.commits.length, dispatch]);

  /* ---------- Derived canvas model ---------- */
  const { nodes, edges } = useMemo(
    () => buildRenderGraph({ graph, impact: state.impact.result, story: state.story }),
    [graph, state.impact.result, state.story],
  );

  /* ---------- Handlers ---------- */
  const loadGraph = useCallback((next: ArchitectureGraph) => dispatch({ type: "loadGraph", graph: next }), [dispatch]);

  const selectRepository = (id: string) => {
    if (id === CUSTOM_UPLOAD_OPTION) {
      setImportState({ open: true, busy: false, error: null });
      return;
    }
    const next = id === importedGraph?.id ? importedGraph : findSample(id);
    if (next) loadGraph(next);
  };

  const runImpact = useCallback(async () => {
    const snapshot = graphRef.current;
    const prompt = state.impactPrompt.trim();
    if (!prompt) {
      dispatch({ type: "setTab", tab: "blast" });
      return;
    }
    dispatch({ type: "setTab", tab: "blast" });
    dispatch({ type: "impactStarted" });
    try {
      const { data, warning } = await requestImpact(snapshot, prompt, state.selectedNodeId);
      if (graphIdRef.current !== snapshot.id) return;
      dispatch({ type: "impactSucceeded", result: data });
      if (warning) notify({ tone: "warning", message: warning });
    } catch (error) {
      if (graphIdRef.current === snapshot.id) dispatch({ type: "impactFailed", error: errorMessage(error) });
    }
  }, [state.impactPrompt, state.selectedNodeId, dispatch, notify]);

  const simulateFrom = useCallback(
    (nodeId: string) => {
      dispatch({ type: "selectNode", nodeId });
      dispatch({ type: "setTab", tab: "blast" });
    },
    [dispatch],
  );

  const nodeActions = useMemo<NodeActions>(
    () => ({
      inspect: (nodeId) => {
        dispatch({ type: "selectNode", nodeId });
        dispatch({ type: "setTab", tab: "inspector" });
      },
      simulateFrom,
      copyPath: (filePath) => {
        navigator.clipboard.writeText(filePath).then(
          () => notify({ tone: "info", message: `Copied ${filePath}` }),
          () => notify({ tone: "error", message: "Clipboard access was denied." }),
        );
      },
    }),
    [dispatch, notify, simulateFrom],
  );

  const narrate = async () => {
    const snapshot = graphRef.current;
    dispatch({ type: "storyNarrationStarted" });
    try {
      const { data, warning } = await requestStory(snapshot);
      if (graphIdRef.current !== snapshot.id) return;
      dispatch({ type: "storyNarrated", narrative: data });
      if (warning) notify({ tone: "warning", message: warning });
      else if (data.engine === "local") notify({ tone: "info", message: "Claude is not configured — showing commit-derived narratives." });
    } catch (error) {
      dispatch({ type: "storyNarrationFailed" });
      notify({ tone: "error", message: errorMessage(error) });
    }
  };

  const importGitLog = (text: string) => {
    try {
      const commits = commitsFromGitLog(text, graph.nodes);
      dispatch({ type: "setCommits", commits });
      const mapped = commits.filter((c) => c.addedNodeIds.length + c.modifiedNodeIds.length > 0).length;
      notify({ tone: "info", message: `Imported ${commits.length} commits; ${mapped} touch components on this map.` });
    } catch (error) {
      notify({ tone: "error", message: errorMessage(error) });
    }
  };

  const addComponent = ({ label, kind, filePath, description }: { label: string; kind: NodeKind; filePath: string; description: string }) => {
    const base = `draft-${kebabCase(label) || "component"}`;
    let id = base;
    for (let n = 2; graph.nodes.some((node) => node.id === id); n++) id = `${base}-${n}`;
    const anchor = graph.nodes.find((node) => node.id === state.selectedNodeId);
    const lowest = Math.max(0, ...graph.nodes.map((node) => node.position.y));
    const node: ArchNode = {
      id,
      type: "component",
      position: anchor ? { x: anchor.position.x + 260, y: anchor.position.y + 40 } : { x: 260, y: lowest + DRAFT_VERTICAL_GAP_PX },
      data: { label, kind, filePath, description, language: filePath.split(".").pop() ?? "ts", code: `// ${label} — not generated yet`, exports: [], imports: [], params: [], keywords: kebabCase(label).split("-"), isDraft: true },
    };
    dispatch({ type: "addDraftNode", node });
  };

  const connect = (connection: Connection) => {
    if (!connection.source || !connection.target) return;
    dispatch({
      type: "addDraftEdge",
      edge: { id: `draft-e-${connection.source}--${connection.target}`, source: connection.source, target: connection.target, relation: "calls", isDraft: true },
    });
  };

  const generateScaffold = async () => {
    const snapshot = graphRef.current;
    dispatch({ type: "scaffoldStarted" });
    try {
      const { data, warning } = await requestScaffold(snapshot);
      if (graphIdRef.current !== snapshot.id) return;
      dispatch({ type: "scaffoldSucceeded", result: data });
      if (warning) notify({ tone: "warning", message: warning });
    } catch (error) {
      dispatch({ type: "scaffoldFailed", error: errorMessage(error) });
    }
  };

  const finishImport = (next: ArchitectureGraph, warning?: string) => {
    setImportedGraph(next);
    loadGraph(next);
    setImportState({ open: false, busy: false, error: null });
    const notes = [warning, ...(next.warnings ?? [])].filter(Boolean).join(" ");
    if (notes) notify({ tone: "warning", message: notes });
  };

  const uploadFile = async (file: File) => {
    setImportState((s) => ({ ...s, busy: true, error: null }));
    try {
      const upload = await readUpload(file);
      if (upload.kind === "graph") return finishImport(upload.graph);
      if (upload.files.length === 0) throw new Error("No supported source files found in the archive.");
      const { data, warning } = await requestRepoFromFiles(upload.name, upload.files);
      finishImport(data, [warning, upload.skipped ? `${upload.skipped} oversized file(s) skipped.` : ""].filter(Boolean).join(" ") || undefined);
    } catch (error) {
      setImportState((s) => ({ ...s, busy: false, error: errorMessage(error) }));
    }
  };

  const analyzeGithub = async (url: string) => {
    setImportState((s) => ({ ...s, busy: true, error: null }));
    try {
      const { data, warning } = await requestRepoFromGithub(url);
      finishImport(data, warning);
    } catch (error) {
      setImportState((s) => ({ ...s, busy: false, error: errorMessage(error) }));
    }
  };

  const exportAll = async () => {
    setIsExporting(true);
    try {
      await exportCodebase(graph);
    } catch (error) {
      notify({ tone: "error", message: `Export failed: ${errorMessage(error)}` });
    } finally {
      setIsExporting(false);
    }
  };

  const notice = state.notice;
  const NoticeIcon = notice ? NOTICE_STYLE[notice.tone].icon : Info;

  return (
    <div className="flex h-dvh flex-col bg-[radial-gradient(ellipse_at_top_left,_rgba(139,92,246,0.10),_transparent_50%),radial-gradient(ellipse_at_bottom_right,_rgba(14,165,233,0.08),_transparent_50%)] bg-zinc-950">
      <TopNav
        graph={graph}
        samples={SAMPLE_REPOSITORIES}
        importedGraph={importedGraph}
        engine={engine}
        isStoryOn={state.story.enabled}
        isImpactActive={state.impact.result !== null || state.impact.status === "running"}
        isExporting={isExporting}
        onSelectRepository={selectRepository}
        onSimulate={() => void runImpact()}
        onToggleStory={() => dispatch({ type: "toggleStory" })}
        onExport={() => void exportAll()}
      />

      <main className="flex min-h-0 flex-1 flex-col lg:flex-row">
        <section className="relative h-[55vh] min-h-0 lg:h-auto lg:basis-[65%]" aria-label="Architecture graph">
          <ReactFlowProvider>
            <ArchitectureCanvas
              graphKey={graph.id}
              nodes={nodes}
              edges={edges}
              actions={nodeActions}
              onNodesChange={(changes) => dispatch({ type: "nodesChanged", changes })}
              onSelectNode={(nodeId) => dispatch({ type: "selectNode", nodeId })}
              onConnect={connect}
              onRemoveDraftEdge={(edgeId) => dispatch({ type: "removeDraftEdge", edgeId })}
            />
          </ReactFlowProvider>

          {state.story.enabled && graph.commits[state.story.index] && (
            <div className="pointer-events-none absolute inset-x-0 top-14 flex justify-center">
              <div className="rounded-full border border-violet-500/40 bg-violet-950/80 px-3 py-1 text-xs text-violet-100 backdrop-blur">
                <span className="font-mono text-violet-300">{graph.commits[state.story.index]!.hash}</span> · {graph.commits[state.story.index]!.phase}
              </div>
            </div>
          )}

          {notice && (
            <div role="status" className={clsx("absolute bottom-4 left-16 right-48 z-10 flex max-w-xl items-start gap-2 rounded-lg border px-3 py-2 text-xs shadow-xl backdrop-blur", NOTICE_STYLE[notice.tone].box)}>
              <NoticeIcon className="mt-0.5 h-3.5 w-3.5 shrink-0" />
              <span className="flex-1 leading-relaxed">{notice.message}</span>
              <button type="button" aria-label="Dismiss" onClick={() => notify(null)} className="opacity-70 hover:opacity-100">
                <X className="h-3.5 w-3.5" />
              </button>
            </div>
          )}
        </section>

        <div className="min-h-0 flex-1 lg:basis-[35%] lg:min-w-[380px]">
          <InspectorPanel
            state={state}
            dispatch={dispatch}
            samplePrompts={SAMPLE_PROMPTS[graph.id] ?? []}
            onRunImpact={() => void runImpact()}
            onSimulate={simulateFrom}
            onNarrate={() => void narrate()}
            onImportGitLog={importGitLog}
            onAddComponent={addComponent}
            onGenerateScaffold={() => void generateScaffold()}
          />
        </div>
      </main>

      <ImportDialog
        open={importState.open}
        isBusy={importState.busy}
        error={importState.error}
        onClose={() => setImportState({ open: false, busy: false, error: null })}
        onUploadFile={(file) => void uploadFile(file)}
        onGithubUrl={(url) => void analyzeGithub(url)}
      />
    </div>
  );
}

"use client";

import clsx from "clsx";
import { Bot, ChevronDown, Cpu, Download, FolderGit2, History, Loader2, Network, Radar } from "lucide-react";
import type { ArchitectureGraph, EngineKind } from "@/lib/types";

export const CUSTOM_UPLOAD_OPTION = "__custom_upload__";

type Props = {
  graph: ArchitectureGraph;
  samples: readonly ArchitectureGraph[];
  importedGraph: ArchitectureGraph | null;
  engine: { engine: EngineKind; model: string | null } | null;
  isStoryOn: boolean;
  isImpactActive: boolean;
  isExporting: boolean;
  onSelectRepository: (id: string) => void;
  onSimulate: () => void;
  onToggleStory: () => void;
  onExport: () => void;
};

function NavButton({ onClick, active, disabled, children, tone }: { onClick: () => void; active?: boolean; disabled?: boolean; children: React.ReactNode; tone: "red" | "violet" | "zinc" }) {
  const tones = {
    red: active ? "border-red-500/60 bg-red-500/15 text-red-200" : "border-zinc-700 text-zinc-300 hover:border-red-500/50 hover:text-red-200",
    violet: active ? "border-violet-500/60 bg-violet-500/15 text-violet-200" : "border-zinc-700 text-zinc-300 hover:border-violet-500/50 hover:text-violet-200",
    zinc: "border-zinc-700 text-zinc-300 hover:border-zinc-500 hover:text-white",
  };
  return (
    <button
      type="button"
      onClick={onClick}
      disabled={disabled}
      aria-pressed={active}
      className={clsx("flex items-center gap-1.5 whitespace-nowrap rounded-lg border px-2.5 py-1.5 text-xs font-medium transition disabled:opacity-50", tones[tone])}
    >
      {children}
    </button>
  );
}

export function TopNav(props: Props) {
  const { graph, samples, importedGraph, engine } = props;

  return (
    <header className="flex shrink-0 flex-wrap items-center gap-3 border-b border-zinc-800/80 bg-zinc-950/80 px-4 py-2.5 backdrop-blur-xl">
      <div className="flex items-center gap-2.5">
        <div className="rounded-lg bg-gradient-to-br from-violet-500 to-sky-500 p-1.5 shadow-lg shadow-violet-900/40">
          <Network className="h-4 w-4 text-white" />
        </div>
        <div className="leading-tight">
          <h1 className="text-sm font-semibold tracking-tight text-zinc-50">CodeArchitect AI</h1>
          <p className="text-[10px] text-zinc-500">Dependency maps · blast radius · time machine</p>
        </div>
      </div>

      <div className="mx-1 hidden h-6 w-px bg-zinc-800 sm:block" />

      <label className="relative flex items-center gap-2 rounded-lg border border-zinc-700 bg-zinc-900/70 py-1 pl-2.5 pr-1 text-xs text-zinc-300">
        <FolderGit2 className="h-3.5 w-3.5 text-zinc-500" />
        <span className="sr-only">Active repository</span>
        <select
          value={graph.id}
          onChange={(e) => props.onSelectRepository(e.target.value)}
          className="max-w-[220px] cursor-pointer appearance-none bg-transparent pr-6 font-medium text-zinc-100 focus:outline-none"
        >
          {samples.map((s) => (
            <option key={s.id} value={s.id} className="bg-zinc-900">
              {s.name}
            </option>
          ))}
          {importedGraph && (
            <option value={importedGraph.id} className="bg-zinc-900">
              {importedGraph.name}
            </option>
          )}
          <option value={CUSTOM_UPLOAD_OPTION} className="bg-zinc-900">
            Custom Upload…
          </option>
        </select>
        <ChevronDown className="pointer-events-none absolute right-2 h-3.5 w-3.5 text-zinc-500" />
      </label>

      <span
        className={clsx(
          "flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-medium ring-1 ring-inset",
          engine?.engine === "claude" ? "bg-violet-500/10 text-violet-300 ring-violet-500/30" : "bg-zinc-800 text-zinc-400 ring-zinc-700",
        )}
        title={engine?.engine === "claude" ? `Analysis by ${engine.model}` : "Deterministic local engine (set ANTHROPIC_API_KEY to enable Claude)"}
      >
        {engine?.engine === "claude" ? <Bot className="h-3 w-3" /> : <Cpu className="h-3 w-3" />}
        {engine ? (engine.engine === "claude" ? "Claude" : "Local engine") : "…"}
      </span>

      <div className="ml-auto flex flex-wrap items-center gap-2">
        <NavButton tone="red" active={props.isImpactActive} onClick={props.onSimulate}>
          <Radar className="h-3.5 w-3.5" /> Simulate Blast Radius
        </NavButton>
        <NavButton tone="violet" active={props.isStoryOn} onClick={props.onToggleStory}>
          <History className="h-3.5 w-3.5" /> Toggle Time-Machine Story
        </NavButton>
        <NavButton tone="zinc" onClick={props.onExport} disabled={props.isExporting}>
          {props.isExporting ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Download className="h-3.5 w-3.5" />} Export Code Base
        </NavButton>
      </div>
    </header>
  );
}

"use client";

import {
  Background,
  BackgroundVariant,
  Controls,
  MiniMap,
  Panel,
  ReactFlow,
  type Connection,
  type EdgeChange,
  type NodeChange,
  type NodeTypes,
} from "@xyflow/react";
import { useCallback, useMemo } from "react";
import { CustomNode, NodeActionsContext, type NodeActions } from "@/components/CustomNode";
import type { ArchNode, RenderEdge, RenderNode } from "@/lib/types";
import { KIND_META, STATUS_META } from "@/lib/ui";

const NODE_TYPES: NodeTypes = { component: CustomNode };

const MINIMAP_STATUS_COLORS: Partial<Record<RenderNode["data"]["status"], string>> = {
  broken: "#ef4444",
  impacted: "#f59e0b",
  modified: "#38bdf8",
  added: "#34d399",
  proposed: "#d946ef",
};

type Props = {
  graphKey: string;
  nodes: RenderNode[];
  edges: RenderEdge[];
  actions: NodeActions;
  onNodesChange: (changes: NodeChange<ArchNode>[]) => void;
  onSelectNode: (nodeId: string | null) => void;
  onConnect: (connection: Connection) => void;
  onRemoveDraftEdge: (edgeId: string) => void;
};

export function ArchitectureCanvas({ graphKey, nodes, edges, actions, onNodesChange, onSelectNode, onConnect, onRemoveDraftEdge }: Props) {
  const handleEdgesChange = useCallback(
    (changes: EdgeChange<RenderEdge>[]) => {
      for (const change of changes) if (change.type === "remove") onRemoveDraftEdge(change.id);
    },
    [onRemoveDraftEdge],
  );

  const isValidConnection = useCallback((c: Connection | RenderEdge) => c.source !== c.target, []);

  const legend = useMemo(
    () =>
      (Object.keys(KIND_META) as Array<keyof typeof KIND_META>).map((kind) => (
        <span key={kind} className="flex items-center gap-1.5">
          <span className="h-2 w-2 rounded-sm" style={{ background: KIND_META[kind].hex }} />
          {KIND_META[kind].label}
        </span>
      )),
    [],
  );

  return (
    <NodeActionsContext.Provider value={actions}>
      <ReactFlow<RenderNode, RenderEdge>
        key={graphKey}
        nodes={nodes}
        edges={edges}
        nodeTypes={NODE_TYPES}
        // RenderNode is ArchNode plus derived fields; position/dimension changes apply to the source nodes.
        onNodesChange={onNodesChange as unknown as (changes: NodeChange<RenderNode>[]) => void}
        onEdgesChange={handleEdgesChange}
        onNodeClick={(_, node) => onSelectNode(node.id)}
        onPaneClick={() => onSelectNode(null)}
        onConnect={onConnect}
        isValidConnection={isValidConnection}
        fitView
        fitViewOptions={{ padding: 0.2 }}
        minZoom={0.2}
        maxZoom={2}
        proOptions={{ hideAttribution: true }}
        colorMode="dark"
      >
        <Background variant={BackgroundVariant.Dots} gap={22} size={1.2} color="#3f3f46" />
        <Controls position="bottom-left" showInteractive={false} />
        <MiniMap
          position="bottom-right"
          pannable
          zoomable
          nodeBorderRadius={6}
          nodeColor={(n) => MINIMAP_STATUS_COLORS[(n as RenderNode).data.status] ?? KIND_META[(n as RenderNode).data.kind].hex}
          className="!rounded-lg !border !border-zinc-800"
        />
        <Panel position="top-left">
          <div className="flex flex-wrap gap-3 rounded-lg border border-zinc-800 bg-zinc-950/80 px-3 py-1.5 text-[11px] text-zinc-400 backdrop-blur">
            {legend}
          </div>
        </Panel>
        <Panel position="top-right">
          <div className="flex gap-3 rounded-lg border border-zinc-800 bg-zinc-950/80 px-3 py-1.5 text-[11px] text-zinc-400 backdrop-blur">
            {(["broken", "impacted", "modified", "proposed"] as const).map((s) => (
              <span key={s} className="flex items-center gap-1.5">
                <span className={`h-2 w-2 rounded-full ${STATUS_META[s].dot}`} />
                {STATUS_META[s].label}
              </span>
            ))}
          </div>
        </Panel>
      </ReactFlow>
    </NodeActionsContext.Provider>
  );
}

"use client";

import { Handle, Position, type NodeProps } from "@xyflow/react";
import clsx from "clsx";
import { Copy, Database, Eye, Layers, Monitor, Network, Zap } from "lucide-react";
import { createContext, memo, useContext, type ComponentType } from "react";
import type { NodeKind, RenderNode } from "@/lib/types";
import { KIND_META, STATUS_META } from "@/lib/ui";

export type NodeActions = {
  inspect: (nodeId: string) => void;
  simulateFrom: (nodeId: string) => void;
  copyPath: (filePath: string) => void;
};

/** Quick actions are injected via context so node data stays serializable. */
export const NodeActionsContext = createContext<NodeActions | null>(null);

const KIND_ICON: Record<NodeKind, ComponentType<{ className?: string }>> = {
  frontend: Monitor,
  api: Network,
  logic: Layers,
  data: Database,
};

function QuickAction({ label, onClick, icon: Icon }: { label: string; onClick: () => void; icon: ComponentType<{ className?: string }> }) {
  return (
    <button
      type="button"
      title={label}
      aria-label={label}
      onClick={(event) => {
        event.stopPropagation();
        onClick();
      }}
      className="nodrag rounded-md p-1 text-zinc-400 transition hover:bg-zinc-700/70 hover:text-zinc-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-violet-400"
    >
      <Icon className="h-3.5 w-3.5" />
    </button>
  );
}

function CustomNodeComponent({ id, data, selected }: NodeProps<RenderNode>) {
  const actions = useContext(NodeActionsContext);
  const kind = KIND_META[data.kind];
  const status = STATUS_META[data.status];
  const Icon = KIND_ICON[data.kind];

  return (
    <div
      className={clsx(
        "group w-[220px] rounded-xl border-2 bg-zinc-900/80 shadow-lg shadow-black/40 backdrop-blur-md transition-[transform,border-color] duration-150 hover:-translate-y-0.5",
        kind.border,
        status.glow,
        data.status === "proposed" && "border-dashed",
        selected && "ring-2 ring-white/70 ring-offset-2 ring-offset-zinc-950",
      )}
    >
      <Handle type="target" position={Position.Top} />

      <div className="flex items-start gap-2 px-3 pt-2.5">
        <div className={clsx("mt-0.5 rounded-md bg-zinc-800/80 p-1.5", kind.text)}>
          <Icon className="h-4 w-4" />
        </div>
        <div className="min-w-0 flex-1">
          <div className="truncate text-[13px] font-semibold leading-tight text-zinc-50" title={data.label}>
            {data.label}
          </div>
          <div className="truncate font-mono text-[10px] text-zinc-500" title={data.filePath}>
            {data.filePath}
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between gap-2 px-3 pb-2 pt-2">
        <span className={clsx("rounded px-1.5 py-0.5 text-[10px] font-medium ring-1 ring-inset", kind.chip)}>{kind.label}</span>
        <span className={clsx("flex items-center gap-1 text-[10px] font-medium", status.text)}>
          <span className={clsx("h-1.5 w-1.5 rounded-full", status.dot, data.status !== "normal" && "animate-pulse")} />
          {status.label}
          {data.impactDepth !== undefined && data.impactDepth > 0 && <span className="text-zinc-500">· {data.impactDepth} hop</span>}
        </span>
      </div>

      {actions && (
        <div className="flex items-center justify-end gap-0.5 border-t border-zinc-800/80 px-2 py-1 opacity-60 transition group-hover:opacity-100">
          <QuickAction label="Inspect code" icon={Eye} onClick={() => actions.inspect(id)} />
          <QuickAction label="Simulate change from here" icon={Zap} onClick={() => actions.simulateFrom(id)} />
          <QuickAction label="Copy file path" icon={Copy} onClick={() => actions.copyPath(data.filePath)} />
        </div>
      )}

      <Handle type="source" position={Position.Bottom} />
    </div>
  );
}

