"use client";

import clsx from "clsx";
import { FileSearch, History, Radar, Wand2, type LucideIcon } from "lucide-react";
import type { Dispatch } from "react";
import { BlastRadiusPanel } from "@/components/inspector/BlastRadiusPanel";
import { BuilderPanel } from "@/components/inspector/BuilderPanel";
import { NodeInspector } from "@/components/inspector/NodeInspector";
import { StoryPanel } from "@/components/inspector/StoryPanel";
import type { InspectorTab, WorkspaceAction, WorkspaceState } from "@/hooks/useWorkspace";
import type { NodeKind } from "@/lib/types";

const TABS: Array<{ id: InspectorTab; label: string; icon: LucideIcon }> = [
  { id: "inspector", label: "Inspector", icon: FileSearch },
  { id: "blast", label: "Blast Radius", icon: Radar },
  { id: "story", label: "Story", icon: History },
  { id: "builder", label: "Builder", icon: Wand2 },
];

type Props = {
  state: WorkspaceState;
  dispatch: Dispatch<WorkspaceAction>;
  samplePrompts: string[];
  onRunImpact: () => void;
  onSimulate: (nodeId: string) => void;
  onNarrate: () => void;
  onImportGitLog: (text: string) => void;
  onAddComponent: (input: { label: string; kind: NodeKind; filePath: string; description: string }) => void;
  onGenerateScaffold: () => void;
};

export function InspectorPanel({ state, dispatch, samplePrompts, ...handlers }: Props) {
  const { graph, activeTab, selectedNodeId } = state;
  const selectedNode = graph.nodes.find((n) => n.id === selectedNodeId);
  const select = (nodeId: string) => dispatch({ type: "selectNode", nodeId });

  return (
    <aside className="flex h-full min-h-0 flex-col border-l border-zinc-800/80 bg-zinc-950/60 backdrop-blur-xl">
      <div role="tablist" aria-label="Inspector modes" className="flex shrink-0 gap-1 border-b border-zinc-800/80 p-1.5">
        {TABS.map(({ id, label, icon: Icon }) => (
          <button
            key={id}
            role="tab"
            type="button"
            id={`tab-${id}`}
            aria-selected={activeTab === id}
            aria-controls={`panel-${id}`}
            onClick={() => dispatch({ type: "setTab", tab: id })}
            className={clsx(
              "flex flex-1 items-center justify-center gap-1.5 rounded-md px-2 py-1.5 text-xs font-medium transition",
              activeTab === id ? "bg-zinc-800 text-zinc-50 shadow-inner" : "text-zinc-500 hover:bg-zinc-900 hover:text-zinc-200",
            )}
          >
            <Icon className="h-3.5 w-3.5" />
            {label}
            {id === "blast" && state.impact.result && <span className="h-1.5 w-1.5 rounded-full bg-red-500" />}
            {id === "builder" && graph.nodes.some((n) => n.data.isDraft) && <span className="h-1.5 w-1.5 rounded-full bg-fuchsia-500" />}
          </button>
        ))}
      </div>

      <div role="tabpanel" id={`panel-${activeTab}`} aria-labelledby={`tab-${activeTab}`} className="scrollbar-thin min-h-0 flex-1 overflow-y-auto p-4">
        {activeTab === "inspector" && <NodeInspector graph={graph} node={selectedNode} onSelectNode={select} onSimulate={handlers.onSimulate} />}
        {activeTab === "blast" && (
          <BlastRadiusPanel
            graph={graph}
            selectedNodeId={selectedNodeId}
            prompt={state.impactPrompt}
            samplePrompts={samplePrompts}
            status={state.impact.status}
            error={state.impact.error}
            result={state.impact.result}
            onPromptChange={(prompt) => dispatch({ type: "setImpactPrompt", prompt })}
            onRun={handlers.onRunImpact}
            onClear={() => dispatch({ type: "clearImpact" })}
            onApply={() => dispatch({ type: "applyImpact" })}
            onSelectNode={select}
          />
        )}
        {activeTab === "story" && (
          <StoryPanel
            graph={graph}
            enabled={state.story.enabled}
            index={state.story.index}
            isPlaying={state.story.isPlaying}
            narrative={state.story.narrative}
            narrationStatus={state.story.status}
            onToggle={() => dispatch({ type: "toggleStory" })}
            onIndexChange={(index) => dispatch({ type: "setStoryIndex", index })}
            onPlayingChange={(isPlaying) => dispatch({ type: "setStoryPlaying", isPlaying })}
            onNarrate={handlers.onNarrate}
            onImportGitLog={handlers.onImportGitLog}
          />
        )}
        {activeTab === "builder" && (
          <BuilderPanel
            graph={graph}
            status={state.scaffold.status}
            error={state.scaffold.error}
            result={state.scaffold.result}
            onAddComponent={handlers.onAddComponent}
            onRemoveDraft={(nodeId) => dispatch({ type: "removeDraftNode", nodeId })}
            onRemoveEdge={(edgeId) => dispatch({ type: "removeDraftEdge", edgeId })}
            onGenerate={handlers.onGenerateScaffold}
            onApply={() => dispatch({ type: "applyScaffold" })}
          />
        )}
      </div>
    </aside>
  );
}

"use client";

import clsx from "clsx";
import { ArrowDownRight, ArrowUpRight, MousePointerClick, Zap } from "lucide-react";
import { CodeBlock } from "@/components/inspector/CodeBlock";
import type { ArchitectureGraph, ArchNode } from "@/lib/types";
import { KIND_META } from "@/lib/ui";

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section className="space-y-1.5">
      <h3 className="text-[11px] font-semibold uppercase tracking-wider text-zinc-500">{title}</h3>
      {children}
    </section>
  );
}

function Chips({ items, empty }: { items: string[]; empty: string }) {
  if (items.length === 0) return <p className="text-xs text-zinc-600">{empty}</p>;
  return (
    <div className="flex flex-wrap gap-1.5">
      {items.map((item) => (
        <code key={item} className="rounded bg-zinc-800/80 px-1.5 py-0.5 font-mono text-[11px] text-zinc-300">
          {item}
        </code>
      ))}
    </div>
  );
}

type Props = {
  graph: ArchitectureGraph;
  node: ArchNode | undefined;
  onSelectNode: (id: string) => void;
  onSimulate: (id: string) => void;
};

export function NodeInspector({ graph, node, onSelectNode, onSimulate }: Props) {
  if (!node) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-3 px-6 text-center text-zinc-500">
        <MousePointerClick className="h-8 w-8 text-zinc-600" />
        <p className="text-sm">Select a component on the canvas to inspect its code, exports and dependencies.</p>
        <p className="text-xs text-zinc-600">Tip: drag from a node's bottom handle to another node to draft a new dependency.</p>
      </div>
    );
  }

  const { data } = node;
  const label = (id: string) => graph.nodes.find((n) => n.id === id)?.data.label ?? id;
  const dependsOn = graph.edges.filter((e) => e.source === node.id);
  const usedBy = graph.edges.filter((e) => e.target === node.id);

  return (
    <div className="space-y-5">
      <header className="space-y-2">
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0">
            <h2 className="truncate text-base font-semibold text-zinc-50">{data.label}</h2>
            <p className="truncate font-mono text-[11px] text-zinc-500">{data.filePath}</p>
          </div>
          <span className={clsx("shrink-0 rounded px-1.5 py-0.5 text-[10px] font-medium ring-1 ring-inset", KIND_META[data.kind].chip)}>
            {KIND_META[data.kind].label}
          </span>
        </div>
        <p className="text-sm leading-relaxed text-zinc-400">{data.description}</p>
        <button
          type="button"
          onClick={() => onSimulate(node.id)}
          className="flex items-center gap-1.5 rounded-md border border-red-500/30 bg-red-500/10 px-2.5 py-1 text-xs font-medium text-red-300 transition hover:bg-red-500/20"
        >
          <Zap className="h-3.5 w-3.5" /> Simulate a change here
        </button>
      </header>

      <Section title="Source">
        <CodeBlock code={data.code} title={`${data.filePath} · ${data.language}`} />
      </Section>

      <div className="grid grid-cols-2 gap-4">
        <Section title="Exports">
          <Chips items={data.exports} empty="None detected" />
        </Section>
        <Section title="Imports">
          <Chips items={data.imports} empty="None detected" />
        </Section>
      </div>

      <Section title="Parameters">
        {data.params.length === 0 ? (
          <p className="text-xs text-zinc-600">None</p>
        ) : (
          <table className="w-full text-left text-xs">
            <tbody>
              {data.params.map((p) => (
                <tr key={p.name} className="border-b border-zinc-800/70 last:border-0">
                  <td className="py-1 pr-2 font-mono text-zinc-200">{p.name}</td>
                  <td className="py-1 pr-2 font-mono text-violet-300">{p.type}</td>
                  <td className="py-1 text-zinc-500">{p.description}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </Section>

      <Section title="Dependencies">
        <ul className="space-y-1 text-xs">
          {dependsOn.map((e) => (
            <li key={e.id}>
              <button type="button" onClick={() => onSelectNode(e.target)} className="flex items-center gap-1.5 text-zinc-300 hover:text-white">
                <ArrowDownRight className="h-3.5 w-3.5 text-zinc-500" />
                {e.relation} <span className="font-medium">{label(e.target)}</span>
                {e.label && <span className="font-mono text-zinc-500">· {e.label}</span>}
              </button>
            </li>
          ))}
          {usedBy.map((e) => (
            <li key={e.id}>
              <button type="button" onClick={() => onSelectNode(e.source)} className="flex items-center gap-1.5 text-zinc-300 hover:text-white">
                <ArrowUpRight className="h-3.5 w-3.5 text-zinc-500" />
                used by <span className="font-medium">{label(e.source)}</span>
              </button>
            </li>
          ))}
          {dependsOn.length + usedBy.length === 0 && <li className="text-zinc-600">Isolated component</li>}
        </ul>
      </Section>
    </div>
  );
}

"use client";

import clsx from "clsx";
import { Bot, CheckCheck, Cpu, Loader2, Radar, X } from "lucide-react";
import { DiffViewer } from "@/components/inspector/DiffViewer";
import type { AsyncStatus } from "@/hooks/useWorkspace";
import type { ArchitectureGraph, ImpactAnalysisResult } from "@/lib/types";
import { SEVERITY_META } from "@/lib/ui";

type Props = {
  graph: ArchitectureGraph;
  selectedNodeId: string | null;
  prompt: string;
  samplePrompts: string[];
  status: AsyncStatus;
  error?: string;
  result: ImpactAnalysisResult | null;
  onPromptChange: (prompt: string) => void;
  onRun: () => void;
  onClear: () => void;
  onApply: () => void;
  onSelectNode: (id: string) => void;
};

const RISK_BANDS = [
  { max: 34, label: "Low", bar: "bg-emerald-500", text: "text-emerald-300" },
  { max: 67, label: "Medium", bar: "bg-amber-500", text: "text-amber-300" },
  { max: 100, label: "High", bar: "bg-red-500", text: "text-red-300" },
];

function RiskMeter({ score }: { score: number }) {
  const band = RISK_BANDS.find((b) => score <= b.max) ?? RISK_BANDS[2]!;
  return (
    <div className="space-y-1">
      <div className="flex items-baseline justify-between text-xs">
        <span className="text-zinc-400">Blast-radius risk</span>
        <span className={clsx("font-semibold", band.text)}>
          {band.label} · {score}/100
        </span>
      </div>
      <div className="h-1.5 overflow-hidden rounded-full bg-zinc-800" role="meter" aria-valuenow={score} aria-valuemin={0} aria-valuemax={100} aria-label="Risk score">
        <div className={clsx("h-full rounded-full transition-all", band.bar)} style={{ width: `${score}%` }} />
      </div>
    </div>
  );
}

export function BlastRadiusPanel(props: Props) {
  const { graph, selectedNodeId, prompt, samplePrompts, status, error, result } = props;
  const isRunning = status === "running";
  const label = (id: string) => graph.nodes.find((n) => n.id === id)?.data.label ?? id;

  return (
    <div className="space-y-5">
      <form
        className="space-y-2"
        onSubmit={(event) => {
          event.preventDefault();
          if (!isRunning) props.onRun();
        }}
      >
        <label htmlFor="impact-prompt" className="text-[11px] font-semibold uppercase tracking-wider text-zinc-500">
          Proposed modification
        </label>
        <textarea
          id="impact-prompt"
          value={prompt}
          onChange={(e) => props.onPromptChange(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) e.currentTarget.form?.requestSubmit();
          }}
          rows={3}
          maxLength={2000}
          placeholder='e.g. "Change `userId` from integer to UUID v4"'
          className="w-full resize-none rounded-lg border border-zinc-700 bg-zinc-950/80 px-3 py-2 text-sm text-zinc-100 placeholder:text-zinc-600 focus:border-violet-500 focus:outline-none focus:ring-2 focus:ring-violet-500/30"
        />
        <div className="flex flex-wrap gap-1.5">
          {samplePrompts.map((s) => (
            <button
              key={s}
              type="button"
              onClick={() => props.onPromptChange(s)}
              className="rounded-full border border-zinc-700 px-2.5 py-0.5 text-[11px] text-zinc-400 transition hover:border-zinc-500 hover:text-zinc-200"
            >
              {s}
            </button>
          ))}
        </div>
        <div className="flex items-center justify-between gap-2 pt-1">
          <span className="truncate text-[11px] text-zinc-500">
            Origin hint: {selectedNodeId ? <span className="text-zinc-300">{label(selectedNodeId)}</span> : "auto-detect from prompt"}
          </span>
          <button
            type="submit"
            disabled={isRunning || !prompt.trim()}
            className="flex shrink-0 items-center gap-1.5 rounded-lg bg-red-600 px-3 py-1.5 text-sm font-medium text-white shadow-lg shadow-red-900/30 transition hover:bg-red-500 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {isRunning ? <Loader2 className="h-4 w-4 animate-spin" /> : <Radar className="h-4 w-4" />}
            {isRunning ? "Analyzing…" : "Run Impact Analysis"}
          </button>
        </div>
      </form>

      {status === "error" && error && <p className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-300">{error}</p>}

      {result && (
        <div className="space-y-4">
          <div className="space-y-3 rounded-lg border border-zinc-800 bg-zinc-900/50 p-3">
            <div className="flex items-center justify-between">
              <span className="flex items-center gap-1.5 text-[11px] text-zinc-500">
                {result.engine === "claude" ? <Bot className="h-3.5 w-3.5 text-violet-400" /> : <Cpu className="h-3.5 w-3.5" />}
                {result.engine === "claude" ? "Claude analysis" : result.scenarioId ? "Local engine · authored scenario" : "Local engine · graph heuristics"}
              </span>
              <button type="button" onClick={props.onClear} className="flex items-center gap-1 text-[11px] text-zinc-500 hover:text-zinc-200">
                <X className="h-3 w-3" /> Clear
              </button>
            </div>
            <RiskMeter score={result.riskScore} />
            <p className="text-sm leading-relaxed text-zinc-300">{result.summary}</p>
          </div>

          <section className="space-y-1.5">
            <h3 className="text-[11px] font-semibold uppercase tracking-wider text-zinc-500">Affected components ({result.impacts.length})</h3>
            <ul className="divide-y divide-zinc-800/80 rounded-lg border border-zinc-800">
              {result.impacts.map((impact) => (
                <li key={impact.nodeId}>
                  <button type="button" onClick={() => props.onSelectNode(impact.nodeId)} className="flex w-full items-start gap-2 px-3 py-2 text-left transition hover:bg-zinc-800/40">
                    <span className={clsx("mt-0.5 shrink-0 rounded px-1.5 py-0.5 text-[10px] font-semibold ring-1 ring-inset", SEVERITY_META[impact.severity].chip)}>
                      {SEVERITY_META[impact.severity].label}
                    </span>
                    <span className="min-w-0">
                      <span className="block text-sm font-medium text-zinc-200">{label(impact.nodeId)}</span>
                      <span className="block text-xs text-zinc-500">{impact.reason}</span>
                    </span>
                  </button>
                </li>
              ))}
            </ul>
          </section>

          <section className="space-y-1.5">
            <div className="flex items-center justify-between">
              <h3 className="text-[11px] font-semibold uppercase tracking-wider text-zinc-500">Required changes ({result.diffs.length} files)</h3>
              {result.diffs.length > 0 && (
                <button type="button" onClick={props.onApply} className="flex items-center gap-1 rounded-md bg-emerald-600/90 px-2 py-1 text-[11px] font-medium text-white hover:bg-emerald-500">
                  <CheckCheck className="h-3.5 w-3.5" /> Apply to model
                </button>
              )}
            </div>
            <DiffViewer items={result.diffs} />
          </section>
        </div>
      )}
    </div>
  );
}

"use client";

import clsx from "clsx";
import { GitCommitHorizontal, History, Loader2, Pause, Play, SkipBack, SkipForward, Sparkles, Upload } from "lucide-react";
import { useState } from "react";
import type { AsyncStatus } from "@/hooks/useWorkspace";
import type { ArchitectureGraph, StoryNarrative } from "@/lib/types";

type Props = {
  graph: ArchitectureGraph;
  enabled: boolean;
  index: number;
  isPlaying: boolean;
  narrative: StoryNarrative | null;
  narrationStatus: AsyncStatus;
  onToggle: () => void;
  onIndexChange: (index: number) => void;
  onPlayingChange: (isPlaying: boolean) => void;
  onNarrate: () => void;
  onImportGitLog: (text: string) => void;
};

const GIT_LOG_HINT = "git log --name-status --date=short";

function GitLogImporter({ onImport, defaultOpen }: { onImport: (text: string) => void; defaultOpen: boolean }) {
  const [open, setOpen] = useState(defaultOpen);
  const [text, setText] = useState("");
  return (
    <div className="rounded-lg border border-zinc-800 bg-zinc-900/40">
      <button type="button" onClick={() => setOpen((v) => !v)} className="flex w-full items-center gap-2 px-3 py-2 text-left text-xs text-zinc-300 hover:text-white">
        <Upload className="h-3.5 w-3.5" /> Import git history
      </button>
      {open && (
        <div className="space-y-2 border-t border-zinc-800 p-3">
          <p className="text-[11px] text-zinc-500">
            Paste the output of <code className="rounded bg-zinc-800 px-1 font-mono text-zinc-300">{GIT_LOG_HINT}</code>. Changed files are matched to components by path.
          </p>
          <textarea
            value={text}
            onChange={(e) => setText(e.target.value)}
            rows={6}
            spellCheck={false}
            placeholder={"commit 4be771d…\nAuthor: …\nDate:   2026-03-19\n\n    feat(auth): stateless JWT sessions\n\nA\tsrc/server/auth/jwt.ts"}
            className="w-full rounded-md border border-zinc-700 bg-zinc-950 px-2 py-1.5 font-mono text-[11px] text-zinc-200 placeholder:text-zinc-700 focus:border-violet-500 focus:outline-none"
          />
          <button
            type="button"
            disabled={!text.trim()}
            onClick={() => onImport(text)}
            className="rounded-md bg-violet-600 px-2.5 py-1 text-xs font-medium text-white hover:bg-violet-500 disabled:opacity-50"
          >
            Build timeline
          </button>
        </div>
      )}
    </div>
  );
}

export function StoryPanel(props: Props) {
  const { graph, enabled, index, isPlaying, narrative, narrationStatus } = props;
  const commits = graph.commits;
  const label = (id: string) => graph.nodes.find((n) => n.id === id)?.data.label ?? id;
  const storyFor = (hash: string) => narrative?.phases.find((p) => p.hash === hash);

  if (commits.length === 0) {
    return (
      <div className="space-y-4">
        <div className="flex flex-col items-center gap-2 py-6 text-center text-zinc-500">
          <History className="h-8 w-8 text-zinc-600" />
          <p className="text-sm">No commit history for this repository yet.</p>
        </div>
        <GitLogImporter onImport={props.onImportGitLog} defaultOpen />
      </div>
    );
  }

  const last = commits.length - 1;
  return (
    <div className="space-y-4">
      <div className="space-y-3 rounded-lg border border-zinc-800 bg-zinc-900/50 p-3">
        <div className="flex items-center justify-between">
          <span className="text-xs text-zinc-400">
            Time machine {enabled ? <span className="text-emerald-400">· on</span> : <span className="text-zinc-600">· off</span>}
          </span>
          <button type="button" onClick={props.onToggle} className="text-[11px] text-zinc-400 underline-offset-2 hover:text-zinc-100 hover:underline">
            {enabled ? "Show current state" : "Replay history on canvas"}
          </button>
        </div>
        <div className="flex items-center gap-2">
          <button type="button" aria-label="Previous commit" disabled={index === 0} onClick={() => props.onIndexChange(index - 1)} className="rounded-md p-1.5 text-zinc-300 hover:bg-zinc-800 disabled:opacity-40">
            <SkipBack className="h-4 w-4" />
          </button>
          <button
            type="button"
            aria-label={isPlaying ? "Pause" : "Play"}
            onClick={() => {
              if (!isPlaying && index === last) props.onIndexChange(0);
              props.onPlayingChange(!isPlaying);
            }}
            className="rounded-full bg-violet-600 p-2 text-white shadow-lg shadow-violet-900/40 hover:bg-violet-500"
          >
            {isPlaying ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4" />}
          </button>
          <button type="button" aria-label="Next commit" disabled={index === last} onClick={() => props.onIndexChange(index + 1)} className="rounded-md p-1.5 text-zinc-300 hover:bg-zinc-800 disabled:opacity-40">
            <SkipForward className="h-4 w-4" />
          </button>
          <input
            type="range"
            min={0}
            max={last}
            value={index}
            onChange={(e) => props.onIndexChange(Number(e.target.value))}
            aria-label="Commit timeline"
            className="flex-1 accent-violet-500"
          />
          <span className="w-12 text-right font-mono text-[11px] text-zinc-500">
            {index + 1}/{commits.length}
          </span>
        </div>
      </div>

      <div className="flex items-center justify-between">
        <h3 className="text-[11px] font-semibold uppercase tracking-wider text-zinc-500">Architecture evolution</h3>
        <button
          type="button"
          onClick={props.onNarrate}
          disabled={narrationStatus === "running"}
          className="flex items-center gap-1 rounded-md border border-violet-500/40 bg-violet-500/10 px-2 py-1 text-[11px] font-medium text-violet-200 hover:bg-violet-500/20 disabled:opacity-50"
        >
          {narrationStatus === "running" ? <Loader2 className="h-3 w-3 animate-spin" /> : <Sparkles className="h-3 w-3" />}
          {narrative?.engine === "claude" ? "Re-narrate" : "Narrate with Claude"}
        </button>
      </div>
      {narrative && <p className="rounded-lg border border-violet-500/20 bg-violet-500/5 px-3 py-2 text-xs leading-relaxed text-violet-100/90">{narrative.overview}</p>}

      <ol className="relative space-y-1 border-l border-zinc-800 pl-4">
        {commits.map((commit, i) => {
          const story = storyFor(commit.hash);
          const isCurrent = enabled && i === index;
          const isFuture = enabled && i > index;
          return (
            <li key={commit.hash} className={clsx("relative transition-opacity", isFuture && "opacity-40")}>
              <span className={clsx("absolute -left-[22px] top-3 h-3 w-3 rounded-full border-2 border-zinc-950", isCurrent ? "bg-violet-400 ring-4 ring-violet-500/20" : "bg-zinc-600")} />
              <button
                type="button"
                onClick={() => props.onIndexChange(i)}
                className={clsx("w-full rounded-lg px-3 py-2 text-left transition", isCurrent ? "bg-violet-500/10 ring-1 ring-violet-500/30" : "hover:bg-zinc-800/40")}
              >
                <div className="flex items-center gap-2 text-[11px] text-zinc-500">
                  <GitCommitHorizontal className="h-3.5 w-3.5" />
                  <span className="font-mono text-zinc-400">{commit.hash}</span>
                  <span>{commit.date}</span>
                  <span className="truncate">· {commit.author}</span>
                </div>
                <div className="mt-0.5 text-sm font-semibold text-zinc-100">{story?.phase ?? commit.phase}</div>
                <div className="font-mono text-[11px] text-zinc-400">{commit.message}</div>
                {(isCurrent || !enabled) && <p className="mt-1.5 text-xs leading-relaxed text-zinc-400">{story?.narrative ?? commit.narrative}</p>}
                {(commit.addedNodeIds.length > 0 || commit.modifiedNodeIds.length > 0) && (
                  <div className="mt-1.5 flex flex-wrap gap-1">
                    {commit.addedNodeIds.map((id) => (
                      <span key={`a-${id}`} className="rounded bg-emerald-500/10 px-1.5 py-0.5 text-[10px] text-emerald-300 ring-1 ring-inset ring-emerald-500/30">+ {label(id)}</span>
                    ))}
                    {commit.modifiedNodeIds.map((id) => (
                      <span key={`m-${id}`} className="rounded bg-sky-500/10 px-1.5 py-0.5 text-[10px] text-sky-300 ring-1 ring-inset ring-sky-500/30">~ {label(id)}</span>
                    ))}
                  </div>
                )}
              </button>
            </li>
          );
        })}
      </ol>

      <GitLogImporter onImport={props.onImportGitLog} defaultOpen={false} />
    </div>
  );
}

"use client";

import clsx from "clsx";
import { CheckCheck, FilePlus2, Loader2, Plus, Trash2, Wand2 } from "lucide-react";
import { useState } from "react";
import { CodeBlock } from "@/components/inspector/CodeBlock";
import { DiffViewer } from "@/components/inspector/DiffViewer";
import type { AsyncStatus } from "@/hooks/useWorkspace";
import { suggestFilePath } from "@/lib/engines/localScaffold";
import type { ArchitectureGraph, NodeKind, ScaffoldResult } from "@/lib/types";
import { KIND_META } from "@/lib/ui";

type Props = {
  graph: ArchitectureGraph;
  status: AsyncStatus;
  error?: string;
  result: ScaffoldResult | null;
  onAddComponent: (input: { label: string; kind: NodeKind; filePath: string; description: string }) => void;
  onRemoveDraft: (nodeId: string) => void;
  onRemoveEdge: (edgeId: string) => void;
  onGenerate: () => void;
  onApply: () => void;
};

const KINDS = Object.keys(KIND_META) as NodeKind[];

export function BuilderPanel({ graph, status, error, result, ...actions }: Props) {
  const [label, setLabel] = useState("");
  const [kind, setKind] = useState<NodeKind>("frontend");
  const [description, setDescription] = useState("");
  const [customPath, setCustomPath] = useState<string | null>(null);

  const filePath = customPath ?? (label.trim() ? suggestFilePath(label, kind) : "");
  const drafts = graph.nodes.filter((n) => n.data.isDraft);
  const draftEdges = graph.edges.filter((e) => e.isDraft);
  const name = (id: string) => graph.nodes.find((n) => n.id === id)?.data.label ?? id;
  const hasWork = drafts.length > 0 || draftEdges.length > 0;

  return (
    <div className="space-y-5">
      <form
        className="space-y-2 rounded-lg border border-zinc-800 bg-zinc-900/50 p-3"
        onSubmit={(e) => {
          e.preventDefault();
          if (!label.trim()) return;
          actions.onAddComponent({ label: label.trim(), kind, filePath, description: description.trim() || `New ${KIND_META[kind].label.toLowerCase()} component.` });
          setLabel("");
          setDescription("");
          setCustomPath(null);
        }}
      >
        <h3 className="text-[11px] font-semibold uppercase tracking-wider text-zinc-500">Add component</h3>
        <div className="grid grid-cols-4 gap-1">
          {KINDS.map((k) => (
            <button
              key={k}
              type="button"
              onClick={() => setKind(k)}
              aria-pressed={kind === k}
              className={clsx("rounded-md border px-1.5 py-1 text-[10px] font-medium transition", kind === k ? `${KIND_META[k].border} ${KIND_META[k].text} bg-zinc-800` : "border-zinc-800 text-zinc-500 hover:text-zinc-300")}
            >
              {KIND_META[k].label}
            </button>
          ))}
        </div>
        <input
          value={label}
          onChange={(e) => setLabel(e.target.value)}
          placeholder='Name, e.g. "Export PDF Button"'
          maxLength={80}
          className="w-full rounded-md border border-zinc-700 bg-zinc-950 px-2.5 py-1.5 text-sm text-zinc-100 placeholder:text-zinc-600 focus:border-violet-500 focus:outline-none"
        />
        <input
          value={filePath}
          onChange={(e) => setCustomPath(e.target.value)}
          placeholder="File path"
          className="w-full rounded-md border border-zinc-800 bg-zinc-950 px-2.5 py-1 font-mono text-[11px] text-zinc-400 placeholder:text-zinc-700 focus:border-violet-500 focus:outline-none"
        />
        <input
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="What should it do? (helps Claude)"
          maxLength={300}
          className="w-full rounded-md border border-zinc-800 bg-zinc-950 px-2.5 py-1 text-xs text-zinc-300 placeholder:text-zinc-700 focus:border-violet-500 focus:outline-none"
        />
        <button type="submit" disabled={!label.trim()} className="flex items-center gap-1.5 rounded-md bg-zinc-100 px-2.5 py-1 text-xs font-medium text-zinc-900 hover:bg-white disabled:opacity-40">
          <Plus className="h-3.5 w-3.5" /> Add to canvas
        </button>
        <p className="text-[11px] text-zinc-500">Then drag from a node&apos;s bottom handle to another node&apos;s top handle: the source will depend on the target.</p>
      </form>

      <section className="space-y-1.5">
        <h3 className="text-[11px] font-semibold uppercase tracking-wider text-zinc-500">Draft changes</h3>
        {!hasWork && <p className="text-xs text-zinc-600">Nothing drafted yet.</p>}
        <ul className="space-y-1">
          {drafts.map((n) => (
            <li key={n.id} className="flex items-center justify-between rounded-md border border-dashed border-fuchsia-500/40 bg-fuchsia-500/5 px-2.5 py-1.5 text-xs">
              <span className="flex items-center gap-1.5 text-fuchsia-200">
                <FilePlus2 className="h-3.5 w-3.5" /> {n.data.label}
                <span className="font-mono text-[10px] text-zinc-500">{n.data.filePath}</span>
              </span>
              <button type="button" aria-label={`Remove ${n.data.label}`} onClick={() => actions.onRemoveDraft(n.id)} className="text-zinc-500 hover:text-red-400">
                <Trash2 className="h-3.5 w-3.5" />
              </button>
            </li>
          ))}
          {draftEdges.map((e) => (
            <li key={e.id} className="flex items-center justify-between rounded-md border border-zinc-800 px-2.5 py-1.5 text-xs text-zinc-300">
              <span>
                {name(e.source)} <span className="text-fuchsia-400">→</span> {name(e.target)}
              </span>
              <button type="button" aria-label="Remove connection" onClick={() => actions.onRemoveEdge(e.id)} className="text-zinc-500 hover:text-red-400">
                <Trash2 className="h-3.5 w-3.5" />
              </button>
            </li>
          ))}
        </ul>
        <button
          type="button"
          onClick={actions.onGenerate}
          disabled={!hasWork || status === "running"}
          className="mt-2 flex w-full items-center justify-center gap-1.5 rounded-lg bg-fuchsia-600 px-3 py-1.5 text-sm font-medium text-white shadow-lg shadow-fuchsia-900/30 hover:bg-fuchsia-500 disabled:opacity-40"
        >
          {status === "running" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Wand2 className="h-4 w-4" />}
          {status === "running" ? "Generating…" : "Generate glue code"}
        </button>
        {status === "error" && error && <p className="text-xs text-red-300">{error}</p>}
      </section>

      {result && (
        <section className="space-y-3">
          <div className="flex items-center justify-between">
            <p className="text-xs text-zinc-400">
              {result.summary} <span className="text-zinc-600">({result.engine === "claude" ? "Claude" : "templates"})</span>
            </p>
            <button type="button" onClick={actions.onApply} className="flex shrink-0 items-center gap-1 rounded-md bg-emerald-600/90 px-2 py-1 text-[11px] font-medium text-white hover:bg-emerald-500">
              <CheckCheck className="h-3.5 w-3.5" /> Apply
            </button>
          </div>
          {result.files.map((f) => (
            <CodeBlock key={f.path} code={f.content} title={`new · ${f.path}`} />
          ))}
          {result.diffs.length > 0 && <DiffViewer items={result.diffs} />}
        </section>
      )}
    </div>
  );
}

"use client";

import clsx from "clsx";
import { ChevronDown, FileCode2 } from "lucide-react";
import { Fragment, useMemo, useState } from "react";
