  let name: string;
  let files: SourceFile[];
  if (body.data.kind === "github") {
    try {
      const ref = parseGithubUrl(body.data.url);
      const extracted = await extractSourceFiles(await downloadRepoArchive(ref));
      name = `${ref.owner}/${ref.repo}`;
      files = extracted.files;
