"use client";

import JSZip from "jszip";
import { GraphSchema } from "@/lib/graphSchema";
import { extractSourceFiles } from "@/lib/engines/zip";
import type { ArchitectureGraph, SourceFile } from "@/lib/types";

export const GRAPH_MANIFEST = "codearchitect.graph.json";
const MANIFEST_FORMAT = "codearchitect/v1";

/** Bundle every component's current code at its file path, plus a manifest that restores the exact graph. */
export async function exportCodebase(graph: ArchitectureGraph): Promise<void> {
  const zip = new JSZip();
  for (const node of graph.nodes) zip.file(node.data.filePath, node.data.code);
  zip.file(GRAPH_MANIFEST, JSON.stringify({ format: MANIFEST_FORMAT, exportedAt: new Date().toISOString(), graph }, null, 2));

  const blob = await zip.generateAsync({ type: "blob", compression: "DEFLATE" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = `${graph.name.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-codebase.zip`;
  anchor.click();
  URL.revokeObjectURL(url);
}

export function parseGraphManifest(text: string): ArchitectureGraph {
  let json: unknown;
  try {
    json = JSON.parse(text);
  } catch {
    throw new Error("The JSON file is not valid JSON.");
  }
  const candidate = (json as { graph?: unknown })?.graph ?? json;
  const parsed = GraphSchema.safeParse(candidate);
  if (!parsed.success) {
    const issue = parsed.error.issues[0];
    throw new Error(`Not a CodeArchitect graph: ${issue?.path.join(".") || "root"} — ${issue?.message ?? "invalid"}`);
  }
  return parsed.data as ArchitectureGraph;
}

export type ImportedUpload = { kind: "graph"; graph: ArchitectureGraph } | { kind: "sources"; name: string; files: SourceFile[]; skipped: number };

/** A `.json` manifest or an exported ZIP restores directly; any other ZIP is treated as source code to analyze. */
export async function readUpload(file: File): Promise<ImportedUpload> {
  if (file.name.toLowerCase().endsWith(".json")) return { kind: "graph", graph: parseGraphManifest(await file.text()) };
  if (!file.name.toLowerCase().endsWith(".zip")) throw new Error("Upload a .zip of your repository or a CodeArchitect .json export.");

  const buffer = await file.arrayBuffer();
  const zip = await JSZip.loadAsync(buffer);
  const manifest = zip.file(GRAPH_MANIFEST);
  if (manifest) return { kind: "graph", graph: parseGraphManifest(await manifest.async("string")) };

  const { files, skipped } = await extractSourceFiles(buffer);
  return { kind: "sources", name: file.name.replace(/\.zip$/i, ""), files, skipped };
}

import type { ArchNode, DependencyEdge, NodeKind } from "@/lib/types";

/**
 * Breadth-first walk over *reverse* dependencies: everything that (transitively)
 * depends on `rootId`. Returns hop distance per reached node, root included at 0.
 * O(V + E).
 */
export function collectDependents(rootId: string, edges: readonly DependencyEdge[]): Map<string, number> {
  const dependentsOf = new Map<string, string[]>();
  for (const edge of edges) {
    const list = dependentsOf.get(edge.target) ?? [];
    list.push(edge.source);
    dependentsOf.set(edge.target, list);
  }

  const depth = new Map<string, number>([[rootId, 0]]);
  const queue: string[] = [rootId];
  for (let head = 0; head < queue.length; head++) {
    const current = queue[head]!;
    const currentDepth = depth.get(current)!;
    for (const dependent of dependentsOf.get(current) ?? []) {
      if (depth.has(dependent)) continue;
      depth.set(dependent, currentDepth + 1);
      queue.push(dependent);
    }
  }
  return depth;
}

/** Edges whose both endpoints are in the impacted set — the propagation path to highlight. */
export function impactPathEdgeIds(edges: readonly DependencyEdge[], impacted: ReadonlySet<string>): Set<string> {
  return new Set(edges.filter((e) => impacted.has(e.source) && impacted.has(e.target)).map((e) => e.id));
}

const KIND_ROW: Record<NodeKind, number> = { frontend: 0, api: 1, logic: 2, data: 3 };
const LAYOUT_COLUMN_SPACING_PX = 250;
const LAYOUT_ROW_SPACING_PX = 190;
const LAYOUT_MAX_PER_ROW = 5;

/**
 * Layered layout: one band per architectural layer (UI → API → logic → data),
 * wrapping wide layers onto extra rows. Deterministic, so re-imports are stable.
 */
export function layoutByKind(nodes: readonly ArchNode[]): ArchNode[] {
  const byKind = new Map<NodeKind, ArchNode[]>();
  for (const node of nodes) {
    const list = byKind.get(node.data.kind) ?? [];
    list.push(node);
    byKind.set(node.data.kind, list);
  }

  const placed: ArchNode[] = [];
  let rowCursor = 0;
  for (const kind of Object.keys(KIND_ROW) as NodeKind[]) {
    const group = byKind.get(kind) ?? [];
    for (let start = 0; start < group.length; start += LAYOUT_MAX_PER_ROW) {
      const row = group.slice(start, start + LAYOUT_MAX_PER_ROW);
      const rowWidth = (row.length - 1) * LAYOUT_COLUMN_SPACING_PX;
      row.forEach((node, i) => {
        placed.push({
          ...node,
          position: { x: i * LAYOUT_COLUMN_SPACING_PX - rowWidth / 2 + 500, y: rowCursor * LAYOUT_ROW_SPACING_PX },
        });
      });
      rowCursor++;
    }
  }
  return placed;
}

export function nodeById(nodes: readonly ArchNode[], id: string): ArchNode | undefined {
  return nodes.find((n) => n.id === id);
}

/** Identifier names a node exposes, stripped of `default`/`type` decorations. */
export function exportedIdentifiers(node: ArchNode): string[] {
  return node.data.exports
    .map((e) => e.replace(/^(default|type|async)\s+/g, "").trim())
    .flatMap((e) => e.split(/\s+/))
    .filter((e) => /^[A-Za-z_$][\w$]*$/.test(e) && e !== "default");
}

export type DiffLine = { lineNo: number; text: string };

export type DiffRowType = "same" | "removed" | "added" | "changed";

export type DiffRow = {
  type: DiffRowType;
  left?: DiffLine;
  right?: DiffLine;
};

export type DiffStats = { added: number; removed: number };

type Op = { kind: "same" | "del" | "add"; text: string };

/** Above this many DP cells (~16 MB of Uint32) fall back to a whole-file replace. */
const MAX_LCS_CELLS = 4_000_000;

function splitLines(text: string): string[] {
  return text.replace(/\r\n/g, "\n").split("\n");
}

/** Classic LCS edit script. O(n·m) time and memory — fine for file-sized snippets. */
function editScript(a: string[], b: string[]): Op[] {
  const n = a.length;
  const m = b.length;
  if (n * m > MAX_LCS_CELLS) {
    return [...a.map((text) => ({ kind: "del" as const, text })), ...b.map((text) => ({ kind: "add" as const, text }))];
  }

  const width = m + 1;
  const lcs = new Uint32Array((n + 1) * width);
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      lcs[i * width + j] =
        a[i] === b[j] ? lcs[(i + 1) * width + j + 1]! + 1 : Math.max(lcs[(i + 1) * width + j]!, lcs[i * width + j + 1]!);
    }
  }

  const ops: Op[] = [];
  let i = 0;
  let j = 0;
  while (i < n && j < m) {
    if (a[i] === b[j]) {
      ops.push({ kind: "same", text: a[i]! });
      i++;
      j++;
    } else if (lcs[(i + 1) * width + j]! >= lcs[i * width + j + 1]!) {
      ops.push({ kind: "del", text: a[i++]! });
    } else {
      ops.push({ kind: "add", text: b[j++]! });
    }
  }
  while (i < n) ops.push({ kind: "del", text: a[i++]! });
  while (j < m) ops.push({ kind: "add", text: b[j++]! });
  return ops;
}

/**
 * Side-by-side rows: runs of deletions and additions are paired line-by-line
 * into `changed` rows so the two columns stay aligned.
 */
export function diffLines(before: string, after: string): { rows: DiffRow[]; stats: DiffStats } {
  const ops = editScript(splitLines(before), splitLines(after));
  const rows: DiffRow[] = [];
  const stats: DiffStats = { added: 0, removed: 0 };
  let leftNo = 1;
  let rightNo = 1;

  for (let k = 0; k < ops.length; ) {
    const op = ops[k]!;
    if (op.kind === "same") {
      rows.push({ type: "same", left: { lineNo: leftNo++, text: op.text }, right: { lineNo: rightNo++, text: op.text } });
      k++;
      continue;
    }

    const removed: string[] = [];
    const added: string[] = [];
    while (k < ops.length && ops[k]!.kind !== "same") {
      const current = ops[k]!;
      (current.kind === "del" ? removed : added).push(current.text);
      k++;
    }
    stats.removed += removed.length;
    stats.added += added.length;

    const span = Math.max(removed.length, added.length);
    for (let r = 0; r < span; r++) {
      const left = r < removed.length ? { lineNo: leftNo++, text: removed[r]! } : undefined;
      const right = r < added.length ? { lineNo: rightNo++, text: added[r]! } : undefined;
      rows.push({ type: left && right ? "changed" : left ? "removed" : "added", left, right });
    }
  }
  return { rows, stats };
}

import { collectDependents, exportedIdentifiers, nodeById } from "@/lib/graph";
import type {
  ArchitectureGraph,
  ArchNode,
  DiffItem,
  ImpactAnalysisResult,
  ImpactScenario,
  NodeImpact,
} from "@/lib/types";

export class ImpactRootNotFoundError extends Error {
  constructor(prompt: string) {
    super(
      `Could not map "${prompt}" to a component. Select a node on the canvas first, or mention a component by name (e.g. "Users Database").`,
    );
    this.name = "ImpactRootNotFoundError";
  }
}

const STOP_WORDS = new Set([
  "the", "and", "for", "from", "into", "with", "change", "changes", "refactor", "replace", "this",
  "that", "what", "will", "break", "use", "using", "instead", "make", "add", "remove", "update",
]);

const MIN_TOKEN_LENGTH = 3;

function tokenize(text: string): string[] {
  return text
    .replace(/([a-z])([A-Z])/g, "$1 $2")
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((t) => t.length >= MIN_TOKEN_LENGTH && !STOP_WORDS.has(t));
}

export function matchScenario(prompt: string, scenarios: readonly ImpactScenario[]): ImpactScenario | undefined {
  return scenarios.find((s) => s.triggers.some((source) => new RegExp(source, "i").test(prompt)));
}

/** Score each node against the prompt; keyword hits weigh most, path hits least. */
export function rankNodesForPrompt(prompt: string, nodes: readonly ArchNode[]): Array<{ id: string; score: number }> {
  const tokens = new Set(tokenize(prompt));
  return nodes
    .map((node) => {
      const { keywords, label, filePath, exports } = node.data;
      let score = 0;
      for (const kw of keywords) if (tokens.has(kw.toLowerCase())) score += 3;
      for (const word of tokenize(label)) if (tokens.has(word)) score += 2;
      for (const ex of exports) for (const word of tokenize(ex)) if (tokens.has(word)) score += 2;
      for (const seg of tokenize(filePath)) if (tokens.has(seg)) score += 1;
      return { id: node.id, score };
    })
    .sort((a, b) => b.score - a.score);
}

/**
 * Choose the node the change originates from. A selected node wins unless the
 * prompt clearly names a different component (scores ≥ 2 points higher).
 */
export function resolveRootNode(prompt: string, graph: ArchitectureGraph, selectedNodeId: string | null): string {
  const ranked = rankNodesForPrompt(prompt, graph.nodes);
  const best = ranked[0];
  const selectedScore = ranked.find((r) => r.id === selectedNodeId)?.score ?? -Infinity;

  if (selectedNodeId && nodeById(graph.nodes, selectedNodeId)) {
    if (!best || best.score - selectedScore < 2) return selectedNodeId;
  }
  if (!best || best.score === 0) throw new ImpactRootNotFoundError(prompt);
  return best.id;
}

function severityForDepth(depth: number): NodeImpact["severity"] {
  if (depth === 0) return "modified";
  return depth === 1 ? "broken" : "impacted";
}

function reasonForDepth(depth: number, rootLabel: string): string {
  if (depth === 0) return "Origin of the change.";
  if (depth === 1) return `Directly consumes ${rootLabel}; its contract changes underneath this file.`;
  return `Transitively depends on ${rootLabel} (${depth} hops); payload or type changes propagate here.`;
}

const RISK_BREADTH_WEIGHT = 70;
const RISK_DEPTH_WEIGHT_PER_HOP = 10;
const RISK_MAX = 100;

export function computeRiskScore(impacts: readonly NodeImpact[], totalNodes: number): number {
  if (totalNodes === 0) return 0;
  const maxDepth = Math.max(0, ...impacts.map((i) => i.depth));
  const breadth = (impacts.length / totalNodes) * RISK_BREADTH_WEIGHT;
  return Math.min(RISK_MAX, Math.round(breadth + maxDepth * RISK_DEPTH_WEIGHT_PER_HOP));
}

/**
 * Heuristic edit when no authored scenario applies: annotate the lines that
 * touch the changed contract so the reviewer sees exactly where to look.
 */
function heuristicDiff(node: ArchNode, root: ArchNode, prompt: string, isRoot: boolean): DiffItem {
  const lines = node.data.code.split("\n");
  const marker = isRoot ? `// CHANGE: ${prompt}` : `// REVIEW: ${root.data.label} contract changes — "${prompt}"`;
  const identifiers = isRoot ? tokenize(prompt) : exportedIdentifiers(root);

  let flagged = 0;
  const annotated = lines.map((line) => {
    const hits = isRoot
      ? identifiers.some((t) => line.toLowerCase().includes(t))
      : identifiers.some((id) => new RegExp(`\\b${id}\\b`).test(line));
    if (!hits || line.trim().startsWith("//") || line.trim() === "") return line;
    flagged++;
    return `${line} // ⚠ affected`;
  });

  const lastImport = annotated.reduce((acc, line, i) => (/^\s*(import|from)\b/.test(line) ? i : acc), -1);
  annotated.splice(lastImport + 1, 0, ...(lastImport >= 0 ? ["", marker] : [marker]));

  return {
    nodeId: node.id,
    filePath: node.data.filePath,
    before: node.data.code,
    after: annotated.join("\n"),
    rationale:
      flagged > 0
        ? `Heuristic: ${flagged} line(s) reference ${isRoot ? "terms from the change request" : `exports of ${root.data.label}`}.`
        : `Heuristic: no direct references found; review the call path through ${root.data.label}.`,
  };
}

export function analyzeImpactLocally(
  graph: ArchitectureGraph,
  prompt: string,
  selectedNodeId: string | null,
): ImpactAnalysisResult {
  const trimmed = prompt.trim();
  if (!trimmed) throw new Error("Describe the change you want to simulate.");

  const scenario = matchScenario(trimmed, graph.scenarios);
  const rootNodeId = scenario?.rootNodeId ?? resolveRootNode(trimmed, graph, selectedNodeId);
  const root = nodeById(graph.nodes, rootNodeId);
  if (!root) throw new ImpactRootNotFoundError(trimmed);

  const depths = collectDependents(rootNodeId, graph.edges);
  const impacts: NodeImpact[] = [...depths.entries()].map(([nodeId, depth]) => ({
    nodeId,
    depth,
    severity: severityForDepth(depth),
    reason: reasonForDepth(depth, root.data.label),
  }));

  for (const extra of scenario?.extraImpacts ?? []) {
    if (depths.has(extra.nodeId) || !nodeById(graph.nodes, extra.nodeId)) continue;
    impacts.push({ nodeId: extra.nodeId, depth: 1, severity: "impacted", reason: extra.reason });
  }
  impacts.sort((a, b) => a.depth - b.depth);

  const diffs: DiffItem[] = scenario
    ? scenario.diffs.flatMap((d) => {
        const node = nodeById(graph.nodes, d.nodeId);
        return node ? [{ nodeId: d.nodeId, filePath: node.data.filePath, before: node.data.code, after: d.after, rationale: d.rationale }] : [];
      })
    : impacts.flatMap((impact) => {
        const node = nodeById(graph.nodes, impact.nodeId);
        return node ? [heuristicDiff(node, root, trimmed, impact.depth === 0)] : [];
      });

  const brokenCount = impacts.filter((i) => i.severity === "broken").length;
  return {
    prompt: trimmed,
    rootNodeId,
    summary:
      scenario?.summary ??
      `"${root.data.label}" is the origin. ${brokenCount} component(s) consume it directly and ${impacts.length - brokenCount - 1} more are reached transitively. Edits below are heuristic markers — run with Claude for concrete code changes.`,
    riskScore: computeRiskScore(impacts, graph.nodes.length),
    impacts,
    diffs,
    engine: "local",
    scenarioId: scenario?.id,
  };
}

import type { ArchNode, CommitSnapshot } from "@/lib/types";

/**
 * Nodes visible at commit `index`: those introduced at or before it, plus nodes
 * no commit introduces (they pre-date the imported history).
 */
export function visibleNodeIdsAt(nodes: readonly ArchNode[], commits: readonly CommitSnapshot[], index: number): Set<string> {
  const introducedAt = new Map<string, number>();
  commits.forEach((commit, i) => {
    for (const id of commit.addedNodeIds) if (!introducedAt.has(id)) introducedAt.set(id, i);
  });
  return new Set(nodes.filter((n) => (introducedAt.get(n.id) ?? -1) <= index).map((n) => n.id));
}

type ParsedCommit = {
  hash: string;
  author: string;
  date: string;
  message: string;
  files: Array<{ status: string; path: string }>;
};

const COMMIT_HEADER = /^commit\s+([0-9a-f]{7,40})/i;
const ONELINE_HEADER = /^([0-9a-f]{7,40})\s+(.+)$/i;
const NAME_STATUS = /^([AMDR])\d*\t(.+)$/;
const SHORT_HASH_LENGTH = 7;

/**
 * Parse `git log --name-status` (default or `--oneline`) output, newest first,
 * into chronological commits.
 */
export function parseGitLog(text: string): ParsedCommit[] {
  const commits: ParsedCommit[] = [];
  let current: ParsedCommit | null = null;

  for (const raw of text.replace(/\r\n/g, "\n").split("\n")) {
    const line = raw.trimEnd();
    const header = COMMIT_HEADER.exec(line);
    const oneline = !header && !NAME_STATUS.test(line) ? ONELINE_HEADER.exec(line) : null;

    if (header || oneline) {
      current = { hash: (header?.[1] ?? oneline![1]!).slice(0, SHORT_HASH_LENGTH), author: "", date: "", message: oneline?.[2] ?? "", files: [] };
      commits.push(current);
      continue;
    }
    if (!current) continue;

    const status = NAME_STATUS.exec(line);
    if (status) {
      // Renames are "R100\told\tnew": keep the destination path.
      const path = status[2]!.split("\t").pop()!;
      current.files.push({ status: status[1]!, path });
    } else if (line.startsWith("Author:")) {
      current.author = line.slice(7).replace(/<.*>/, "").trim();
    } else if (line.startsWith("Date:")) {
      current.date = line.slice(5).trim();
    } else if (/^\s{4}\S/.test(raw) && !current.message) {
      current.message = line.trim();
    }
  }
  return commits.reverse();
}

function normalizePath(path: string): string {
  return path.replace(/\\/g, "/").replace(/^\.?\//, "").toLowerCase();
}

/** Match a changed file to a node by path suffix in either direction. */
export function nodeIdForPath(path: string, nodes: readonly ArchNode[]): string | undefined {
  const target = normalizePath(path);
  return nodes.find((n) => {
    const nodePath = normalizePath(n.data.filePath);
    return nodePath === target || nodePath.endsWith(`/${target}`) || target.endsWith(`/${nodePath}`);
  })?.id;
}

export function commitsFromGitLog(text: string, nodes: readonly ArchNode[]): CommitSnapshot[] {
  const parsed = parseGitLog(text);
  if (parsed.length === 0) {
    throw new Error("No commits found. Paste the output of `git log --name-status` (default or --oneline format).");
  }

  const seen = new Set<string>();
  return parsed.map((commit, i) => {
    const added: string[] = [];
    const modified: string[] = [];
    for (const file of commit.files) {
      const id = nodeIdForPath(file.path, nodes);
      if (!id) continue;
      if (file.status === "A" && !seen.has(id)) {
        added.push(id);
        seen.add(id);
      } else if (!modified.includes(id) && !added.includes(id)) {
        modified.push(id);
      }
    }
    const touched = [...added, ...modified].map((id) => nodes.find((n) => n.id === id)?.data.label).filter(Boolean);
    return {
      hash: commit.hash,
      message: commit.message || "(no message)",
      author: commit.author || "unknown",
      date: commit.date,
      phase: `Step ${i + 1}`,
      narrative: touched.length
        ? `${commit.message}. Touches ${touched.join(", ")} (${commit.files.length} file(s) changed).`
        : `${commit.message}. No mapped components changed (${commit.files.length} file(s)).`,
      addedNodeIds: added,
      modifiedNodeIds: modified,
    };
  });
}

import { layoutByKind } from "@/lib/graph";
import type { ArchitectureGraph, ArchNode, CodeParam, DependencyEdge, NodeKind, SourceFile } from "@/lib/types";

const SOURCE_EXTENSIONS = /\.(tsx?|jsx?|mjs|cjs|py|go|java|kt|rb|cs|php|vue|svelte)$/i;
const IGNORED_PATHS =
  /(^|\/)(node_modules|dist|build|out|\.next|\.git|vendor|venv|\.venv|__pycache__|coverage|target)(\/|$)|\.d\.ts$|(\.|_)(test|spec|stories)\.|(^|\/)(__tests__|tests?)\//i;
const CONFIG_FILES = /(^|\/)[^/]*(config|rc)\.(c|m)?(js|ts)$/i;

export const MAX_GRAPH_FILES = 60;
const MAX_NODE_CODE_LINES = 120;

const KIND_RULES: Array<{ kind: NodeKind; pattern: RegExp }> = [
  { kind: "data", pattern: /(^|\/)(db|database|models?|schemas?|prisma|repositor(y|ies)|migrations?|cache|redis|entities|dal|store)(\/|\.|_|$)/i },
  { kind: "api", pattern: /(^|\/)(api|routes?|routers?|endpoints?|handlers?|urls\.py|views\.py)(\/|\.|$)|route\.(t|j)s$/i },
  { kind: "frontend", pattern: /\.(tsx|jsx|vue|svelte)$|(^|\/)(components|pages|screens|ui|views|app\/.*page)(\/|\.|$)/i },
];

export function classifyPath(path: string): NodeKind {
  return KIND_RULES.find((rule) => rule.pattern.test(path))?.kind ?? "logic";
}

export function isAnalyzableSource(path: string): boolean {
  return SOURCE_EXTENSIONS.test(path) && !IGNORED_PATHS.test(path) && !CONFIG_FILES.test(path);
}

const JS_IMPORT = /(?:import\s[^'"]*?from\s*|import\s*\(\s*|require\s*\(\s*|export\s[^'"]*?from\s*)['"]([^'"]+)['"]/g;
const PY_IMPORT = /^\s*(?:from\s+([.\w]+)\s+import|import\s+([.\w]+))/gm;
const JS_EXPORT = /export\s+(default\s+)?(?:async\s+)?(?:function\*?|const|let|class|type|interface|enum)\s+([A-Za-z_$][\w$]*)/g;
const PY_EXPORT = /^(?:async\s+)?(?:def|class)\s+([A-Za-z_]\w*)/gm;
const FIRST_SIGNATURE = /(?:function\s+\w+|def\s+\w+|\w+\s*=\s*(?:async\s*)?)\s*\(([^)]*)\)/;

export function extractImports(file: SourceFile): string[] {
  const specs = new Set<string>();
  const pattern = file.path.endsWith(".py") ? PY_IMPORT : JS_IMPORT;
  for (const match of file.content.matchAll(pattern)) {
    const spec = match[1] ?? match[2];
    if (spec) specs.add(spec);
  }
  return [...specs];
}

export function extractExports(file: SourceFile): string[] {
  if (file.path.endsWith(".py")) {
    return [...file.content.matchAll(PY_EXPORT)].map((m) => m[1]!).filter((n) => !n.startsWith("_"));
  }
  return [...file.content.matchAll(JS_EXPORT)].map((m) => (m[1] ? `default ${m[2]}` : m[2]!));
}

function extractParams(file: SourceFile): CodeParam[] {
  const signature = FIRST_SIGNATURE.exec(file.content)?.[1];
  if (!signature) return [];
  return signature
    .split(",")
    .map((p) => p.trim())
    .filter((p) => p && p !== "self")
    .map((p) => {
      const [name, type] = p.split(/:(.*)/s).map((s) => s?.trim());
      return { name: (name ?? p).replace(/[{}?]/g, "").trim(), type: type || "unknown" };
    });
}

function stripExtension(path: string): string {
  return path.replace(/\.(tsx?|jsx?|mjs|cjs|py|vue|svelte)$/i, "").replace(/\/index$/, "");
}

function joinPath(base: string, relative: string): string {
  const parts = base.split("/").slice(0, -1);
  for (const segment of relative.split("/")) {
    if (segment === "..") parts.pop();
    else if (segment !== ".") parts.push(segment);
  }
  return parts.join("/");
}

/** Resolve an import specifier to a file in the set; supports `./`, `../`, `@/` and `~/` aliases and Python modules. */
export function resolveImport(fromPath: string, spec: string, index: ReadonlyMap<string, string>): string | undefined {
  let candidate: string | undefined;
  if (spec.startsWith(".") && !fromPath.endsWith(".py")) candidate = joinPath(fromPath, spec);
  else if (/^[@~]\//.test(spec)) candidate = spec.slice(2);
  else if (fromPath.endsWith(".py")) candidate = spec.replace(/^\.+/, "").replace(/\./g, "/");
  if (!candidate) return undefined;

  const key = stripExtension(candidate);
  return index.get(key) ?? index.get(`src/${key}`) ?? [...index.entries()].find(([k]) => k.endsWith(`/${key}`))?.[1];
}

function slugify(path: string): string {
  return stripExtension(path).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

function labelFor(path: string): string {
  const parts = stripExtension(path).split("/");
  const base = parts.pop() ?? path;
  // Next.js-style `page`/`route` files are named after their folder.
  const name = ["page", "route", "index", "layout"].includes(base) ? `${parts.pop() ?? base}/${base}` : base;
  return name.replace(/[-_]/g, " ").replace(/([a-z])([A-Z])/g, "$1 $2").replace(/\b\w/g, (c) => c.toUpperCase());
}

function languageFor(path: string): string {
  return path.split(".").pop()?.toLowerCase() ?? "text";
}

/** Prefer files that are more likely to be architectural seams: routes, services, schemas over leaf UI. */
function relevance(file: SourceFile): number {
  const kind = classifyPath(file.path);
  const kindWeight = { api: 4, data: 4, logic: 3, frontend: 2 }[kind];
  const depthPenalty = file.path.split("/").length * 0.1;
  return kindWeight - depthPenalty + Math.min(file.content.length / 20_000, 1);
}

export function selectGraphFiles(files: readonly SourceFile[]): { selected: SourceFile[]; warnings: string[] } {
  const candidates = files.filter((f) => isAnalyzableSource(f.path));
  const warnings: string[] = [];
  if (candidates.length === 0) warnings.push("No supported source files found (ts, js, py, go, java, rb, cs, php, vue, svelte).");
  if (candidates.length > MAX_GRAPH_FILES) {
    warnings.push(`Showing the ${MAX_GRAPH_FILES} most architecturally relevant of ${candidates.length} source files.`);
  }
  const selected = [...candidates].sort((a, b) => relevance(b) - relevance(a)).slice(0, MAX_GRAPH_FILES);
  return { selected, warnings };
}

export function truncateCode(content: string): string {
  const lines = content.split("\n");
  if (lines.length <= MAX_NODE_CODE_LINES) return content;
  return [...lines.slice(0, MAX_NODE_CODE_LINES), `// … ${lines.length - MAX_NODE_CODE_LINES} more lines`].join("\n");
}

/**
 * Deterministic file-level dependency graph: one node per relevant source file,
 * one edge per resolvable internal import.
 */
export function buildHeuristicGraph(name: string, files: readonly SourceFile[]): ArchitectureGraph {
  const { selected, warnings } = selectGraphFiles(files);
  const index = new Map(selected.map((f) => [stripExtension(f.path), f.path]));
  const idForPath = new Map(selected.map((f) => [f.path, slugify(f.path)]));

  const nodes: ArchNode[] = selected.map((file) => ({
    id: idForPath.get(file.path)!,
    type: "component",
    position: { x: 0, y: 0 },
    data: {
      label: labelFor(file.path),
      kind: classifyPath(file.path),
      filePath: file.path,
      description: `${file.content.split("\n").length} lines · detected by path heuristics`,
      language: languageFor(file.path),
      code: truncateCode(file.content),
      exports: extractExports(file),
      imports: extractImports(file),
      params: extractParams(file),
      keywords: slugify(file.path).split("-").filter((s) => s.length >= 3),
    },
  }));

  const edges: DependencyEdge[] = [];
  const seen = new Set<string>();
  for (const file of selected) {
    for (const spec of extractImports(file)) {
      const targetPath = resolveImport(file.path, spec, index);
      if (!targetPath || targetPath === file.path) continue;
      const source = idForPath.get(file.path)!;
      const target = idForPath.get(targetPath)!;
      const id = `e-${source}--${target}`;
      if (seen.has(id)) continue;
      seen.add(id);
      edges.push({ id, source, target, relation: "imports" });
    }
  }

  return {
    id: `import-${slugify(name)}-${Date.now().toString(36)}`,
    name,
    description: `${nodes.length} components and ${edges.length} internal imports mapped heuristically.`,
    nodes: layoutByKind(nodes),
    edges,
    commits: [],
    scenarios: [],
    warnings,
  };
}

import { nodeById } from "@/lib/graph";
import type { ArchitectureGraph, ArchNode, DiffItem, NodeKind, ScaffoldFile, ScaffoldResult } from "@/lib/types";

function words(label: string): string[] {
  return label.replace(/([a-z])([A-Z])/g, "$1 $2").split(/[^A-Za-z0-9]+/).filter(Boolean);
}
export const pascalCase = (label: string) => words(label).map((w) => w[0]!.toUpperCase() + w.slice(1).toLowerCase()).join("");
export const camelCase = (label: string) => {
  const p = pascalCase(label);
  return p ? p[0]!.toLowerCase() + p.slice(1) : "component";
};
export const kebabCase = (label: string) => words(label).map((w) => w.toLowerCase()).join("-");

/** Conventional file location for a new component of the given kind (Next.js App Router layout). */
export function suggestFilePath(label: string, kind: NodeKind): string {
  switch (kind) {
    case "frontend":
      return `src/components/${pascalCase(label)}.tsx`;
    case "api":
      return `src/app/api/${kebabCase(label)}/route.ts`;
    case "logic":
      return `src/server/services/${camelCase(label)}.ts`;
    case "data":
      return `src/server/db/${kebabCase(label)}.ts`;
  }
}

/** The identifier other files import to use this component. */
export function primaryExport(label: string, kind: NodeKind): string {
  switch (kind) {
    case "frontend":
      return pascalCase(label);
    case "api":
      return "POST";
    case "logic":
      return `${camelCase(label)}Service`;
    case "data":
      return `${camelCase(label)}Repo`;
  }
}

function importSpecifier(filePath: string): string {
  return `@/${filePath.replace(/^src\//, "").replace(/\.(tsx?|jsx?)$/, "")}`;
}

function importLine(dep: ArchNode): string | null {
  if (dep.data.kind === "api") return null; // routes are reached over HTTP, not imported
  const name = primaryExport(dep.data.label, dep.data.kind);
  const clause = dep.data.kind === "frontend" ? name : `{ ${name} }`;
  return `import ${clause} from "${importSpecifier(dep.data.filePath)}";`;
}

function apiCall(dep: ArchNode): string {
  const route = dep.data.filePath.match(/app(\/api\/.+)\/route\.[jt]s$/)?.[1] ?? `/api/${kebabCase(dep.data.label)}`;
  return `fetch("${route}", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(payload) })`;
}

function templateFor(node: ArchNode, deps: ArchNode[]): string {
  const { label, kind } = node.data;
  const imports = deps.map(importLine).filter((l): l is string => l !== null);
  const header = imports.length ? `${imports.join("\n")}\n\n` : "";
  const firstLogic = deps.find((d) => d.data.kind === "logic" || d.data.kind === "data");
  const firstApi = deps.find((d) => d.data.kind === "api");

  switch (kind) {
    case "frontend": {
      const action = firstApi
        ? `    const response = await ${apiCall(firstApi).replace("payload", "{}")};\n    if (!response.ok) throw new Error(\`${label} failed: \${response.status}\`);`
        : `    await Promise.resolve();`;
      return `"use client";

${header}import { useState } from "react";

export default function ${pascalCase(label)}() {
  const [isPending, setIsPending] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleClick() {
    setIsPending(true);
    setError(null);
    try {
${action}
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setIsPending(false);
    }
  }

  return (
    <div>
      <button type="button" onClick={handleClick} disabled={isPending}>
        {isPending ? "Working…" : "${label}"}
      </button>
      {error && <p role="alert">{error}</p>}
    </div>
  );
}
`;
    }
    case "api": {
      const call = firstLogic ? `await ${primaryExport(firstLogic.data.label, firstLogic.data.kind)}.execute(body)` : "body";
      return `import { NextResponse } from "next/server";
${header}export async function POST(request: Request) {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "invalid JSON body" }, { status: 400 });
  }

  const result = ${call};
  return NextResponse.json(result, { status: 200 });
}
`;
    }
    case "logic": {
      const call = firstLogic ? `return ${primaryExport(firstLogic.data.label, firstLogic.data.kind)}.execute(input);` : "return { ok: true, input };";
      return `${header}export const ${primaryExport(label, kind)} = {
  async execute(input: unknown) {
    ${call}
  },
};
`;
    }
    case "data":
      return `${header}import { Pool } from "pg";

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

export const ${primaryExport(label, kind)} = {
  async execute(input: unknown) {
    const { rows } = await pool.query("SELECT $1::jsonb AS payload", [JSON.stringify(input)]);
    return rows[0];
  },
};
`;
  }
}

/** Insert an import after the last import, plus a JSX usage before the outermost closing tag when wiring UI into UI. */
function wireIntoExisting(source: ArchNode, target: ArchNode): DiffItem {
  const lines = source.data.code.split("\n");
  const line = importLine(target);
  const lastImport = lines.reduce((acc, l, i) => (/^\s*import\b/.test(l) ? i : acc), -1);
  if (line) lines.splice(lastImport + 1, 0, line);

  let usage = "imported";
  if (target.data.kind === "frontend" && /\.(tsx|jsx)$/.test(source.data.filePath)) {
    const closing = lines.reduce((acc, l, i) => (/^\s*<\/\w+>\s*$/.test(l) ? i : acc), -1);
    if (closing > 0) {
      const indent = (lines[closing]!.match(/^\s*/)?.[0] ?? "") + "  ";
      lines.splice(closing, 0, `${indent}<${pascalCase(target.data.label)} />`);
      usage = "rendered";
    }
  } else if (target.data.kind === "api") {
    lines.push("", `export async function call${pascalCase(target.data.label)}(payload: unknown) {`, `  return ${apiCall(target)}.then((r) => r.json());`, "}");
    usage = "called via a typed fetch helper";
  }

  return {
    nodeId: source.id,
    filePath: source.data.filePath,
    before: source.data.code,
    after: lines.join("\n"),
    rationale: `Wire in new ${target.data.label} (${usage}).`,
  };
}

export function scaffoldLocally(graph: ArchitectureGraph): ScaffoldResult {
  const drafts = graph.nodes.filter((n) => n.data.isDraft);
  const draftEdges = graph.edges.filter((e) => e.isDraft);
  if (drafts.length === 0 && draftEdges.length === 0) {
    throw new Error("Add a component or draw a connection in the builder first.");
  }

  const files: ScaffoldFile[] = drafts.map((node) => {
    const deps = graph.edges
      .filter((e) => e.source === node.id)
      .map((e) => nodeById(graph.nodes, e.target))
      .filter((n): n is ArchNode => Boolean(n));
    return { nodeId: node.id, path: node.data.filePath, content: templateFor(node, deps) };
  });

  // Existing files only change when a new edge makes them depend on something.
  const diffsBySource = new Map<string, DiffItem>();
  for (const edge of draftEdges) {
    const source = nodeById(graph.nodes, edge.source);
    const target = nodeById(graph.nodes, edge.target);
    if (!source || !target || source.data.isDraft) continue;
    const existing = diffsBySource.get(source.id);
    const base = existing ? { ...source, data: { ...source.data, code: existing.after } } : source;
    const diff = wireIntoExisting(base, target);
    diffsBySource.set(source.id, {
      ...diff,
      before: source.data.code,
      rationale: existing ? `${existing.rationale} ${diff.rationale}` : diff.rationale,
    });
  }

  return {
    files,
    diffs: [...diffsBySource.values()],
    summary: `Generated ${files.length} new file(s) and ${diffsBySource.size} wiring edit(s) from templates.`,
    engine: "local",
  };
}

import JSZip from "jszip";
import type { SourceFile } from "@/lib/types";
import { isAnalyzableSource } from "@/lib/engines/heuristicGraph";

export const MAX_ARCHIVE_BYTES = 50 * 1024 * 1024;
const MAX_SOURCE_FILE_BYTES = 200 * 1024;

/**
 * Extract analyzable source files from a ZIP. GitHub archives wrap everything
 * in a single `<repo>-<sha>/` folder, which is stripped.
 */
export async function extractSourceFiles(data: ArrayBuffer | Uint8Array): Promise<{ files: SourceFile[]; skipped: number }> {
  if (data.byteLength > MAX_ARCHIVE_BYTES) {
    throw new Error(`Archive is ${(data.byteLength / 1e6).toFixed(1)} MB; the limit is ${MAX_ARCHIVE_BYTES / 1e6} MB.`);
  }
  const zip = await JSZip.loadAsync(data);
  const entries = Object.values(zip.files).filter((entry) => !entry.dir);

  const roots = new Set(entries.map((e) => e.name.split("/")[0]));
  const stripPrefix = roots.size === 1 && entries.every((e) => e.name.includes("/"));

  const files: SourceFile[] = [];
  let skipped = 0;
  for (const entry of entries) {
    const path = stripPrefix ? entry.name.slice(entry.name.indexOf("/") + 1) : entry.name;
    if (path.includes("..") || !isAnalyzableSource(path)) continue;
    const content = await entry.async("string");
    if (content.length > MAX_SOURCE_FILE_BYTES) {
      skipped++;
      continue;
    }
    files.push({ path, content });
  }
  return { files, skipped };
}

