import type { ArchNode, DependencyEdge, NodeKind } from "@/lib/types";

/**
 * Breadth-first walk over *reverse* dependencies: everything that (transitively)
 * depends on `rootId`. Returns hop distance per reached node, root included at 0.
 * O(V + E).
 */
export function collectDependents(rootId: string, edges: readonly DependencyEdge[]): Record<string, number> {
  const dependentsOf = new Map<string, string[]>();
  for (const edge of edges) {
    const list = dependentsOf.get(edge.target) ?? [];
    list.push(edge.source);
    dependentsOf.set(edge.target, list);
  }

  const depth: Record<string, number> = { [rootId]: 0 };
  const queue: string[] = [rootId];
  for (let head = 0; head < queue.length; head++) {
    const current = queue[head]!;
    const currentDepth = depth[current]!;
    for (const dependent of dependentsOf.get(current) ?? []) {
      if (dependent in depth) continue;
      depth[dependent] = currentDepth + 1;
      queue.push(dependent);
    }
  }
  return depth;
}

/** Edges whose both endpoints are in the impacted set — the propagation path to highlight. */
export function impactPathEdgeIds(edges: readonly DependencyEdge[], impacted: ReadonlySet<string>): Set<string> {
  return new Set(edges.filter((e) => impacted.has(e.source) && impacted.has(e.target)).map((e) => e.id));
}

const KIND_ROW: Record<NodeKind, number> = { frontend: 0, api: 1, logic: 2, data: 3 };
const LAYOUT_COLUMN_SPACING_PX = 250;
const LAYOUT_ROW_SPACING_PX = 190;
const LAYOUT_MAX_PER_ROW = 5;

/**
 * Layered layout: one band per architectural layer (UI → API → logic → data),
 * wrapping wide layers onto extra rows. Deterministic, so re-imports are stable.
 */
export function layoutByKind(nodes: readonly ArchNode[]): ArchNode[] {
  const byKind = new Map<NodeKind, ArchNode[]>();
  for (const node of nodes) {
    const list = byKind.get(node.data.kind) ?? [];
    list.push(node);
    byKind.set(node.data.kind, list);
  }

  const placed: ArchNode[] = [];
  let rowCursor = 0;
  for (const kind of Object.keys(KIND_ROW) as NodeKind[]) {
    const group = byKind.get(kind) ?? [];
    for (let start = 0; start < group.length; start += LAYOUT_MAX_PER_ROW) {
      const row = group.slice(start, start + LAYOUT_MAX_PER_ROW);
      const rowWidth = (row.length - 1) * LAYOUT_COLUMN_SPACING_PX;
      row.forEach((node, i) => {
        placed.push({
          ...node,
          position: { x: i * LAYOUT_COLUMN_SPACING_PX - rowWidth / 2 + 500, y: rowCursor * LAYOUT_ROW_SPACING_PX },
        });
      });
      rowCursor++;
    }
  }
  return placed;
}

export function nodeById(nodes: readonly ArchNode[], id: string): ArchNode | undefined {
  return nodes.find((n) => n.id === id);
}

/** Identifier names a node exposes, stripped of `default`/`type` decorations. */
export function exportedIdentifiers(node: ArchNode): string[] {
  return node.data.exports
    .map((e) => e.replace(/^(default|type|async)\s+/g, "").trim())
    .flatMap((e) => e.split(/\s+/))
    .filter((e) => /^[A-Za-z_$][\w$]*$/.test(e) && e !== "default");
}

import { collectDependents, exportedIdentifiers, nodeById } from "@/lib/graph";
import type {
  ArchitectureGraph,
  ArchNode,
  DiffItem,
  ImpactAnalysisResult,
  ImpactScenario,
  NodeImpact,
} from "@/lib/types";

export class ImpactRootNotFoundError extends Error {
  constructor(prompt: string) {
    super(
      `Could not map "${prompt}" to a component. Select a node on the canvas first, or mention a component by name (e.g. "Users Database").`,
    );
    this.name = "ImpactRootNotFoundError";
  }
}

const STOP_WORDS = new Set([
  "the", "and", "for", "from", "into", "with", "change", "changes", "refactor", "replace", "this",
  "that", "what", "will", "break", "use", "using", "instead", "make", "add", "remove", "update",
]);

const MIN_TOKEN_LENGTH = 3;

function tokenize(text: string): string[] {
  return text
    .replace(/([a-z])([A-Z])/g, "$1 $2")
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((t) => t.length >= MIN_TOKEN_LENGTH && !STOP_WORDS.has(t));
}

export function matchScenario(prompt: string, scenarios: readonly ImpactScenario[]): ImpactScenario | undefined {
  return scenarios.find((s) => s.triggers.some((source) => new RegExp(source, "i").test(prompt)));
}

/** Score each node against the prompt; keyword hits weigh most, path hits least. */
export function rankNodesForPrompt(prompt: string, nodes: readonly ArchNode[]): Array<{ id: string; score: number }> {
  const tokens = new Set(tokenize(prompt));
  return nodes
    .map((node) => {
      const { keywords, label, filePath, exports } = node.data;
      let score = 0;
      for (const kw of keywords) if (tokens.has(kw.toLowerCase())) score += 3;
      for (const word of tokenize(label)) if (tokens.has(word)) score += 2;
      for (const ex of exports) for (const word of tokenize(ex)) if (tokens.has(word)) score += 2;
      for (const seg of tokenize(filePath)) if (tokens.has(seg)) score += 1;
      return { id: node.id, score };
    })
    .sort((a, b) => b.score - a.score);
}

/**
 * Choose the node the change originates from. A selected node wins unless the
 * prompt clearly names a different component (scores ≥ 2 points higher).
 */
export function resolveRootNode(prompt: string, graph: ArchitectureGraph, selectedNodeId: string | null): string {
  const ranked = rankNodesForPrompt(prompt, graph.nodes);
  const best = ranked[0];
  const selectedScore = ranked.find((r) => r.id === selectedNodeId)?.score ?? -Infinity;

  if (selectedNodeId && nodeById(graph.nodes, selectedNodeId)) {
    if (!best || best.score - selectedScore < 2) return selectedNodeId;
  }
  if (!best || best.score === 0) throw new ImpactRootNotFoundError(prompt);
  return best.id;
}

function severityForDepth(depth: number): NodeImpact["severity"] {
  if (depth === 0) return "modified";
  return depth === 1 ? "broken" : "impacted";
}

function reasonForDepth(depth: number, rootLabel: string): string {
  if (depth === 0) return "Origin of the change.";
  if (depth === 1) return `Directly consumes ${rootLabel}; its contract changes underneath this file.`;
  return `Transitively depends on ${rootLabel} (${depth} hops); payload or type changes propagate here.`;
}

const RISK_BREADTH_WEIGHT = 70;
const RISK_DEPTH_WEIGHT_PER_HOP = 10;
const RISK_MAX = 100;

export function computeRiskScore(impacts: readonly NodeImpact[], totalNodes: number): number {
  if (totalNodes === 0) return 0;
  const maxDepth = Math.max(0, ...impacts.map((i) => i.depth));
  const breadth = (impacts.length / totalNodes) * RISK_BREADTH_WEIGHT;
  return Math.min(RISK_MAX, Math.round(breadth + maxDepth * RISK_DEPTH_WEIGHT_PER_HOP));
}

/**
 * Heuristic edit when no authored scenario applies: annotate the lines that
 * touch the changed contract so the reviewer sees exactly where to look.
 */
function heuristicDiff(node: ArchNode, root: ArchNode, prompt: string, isRoot: boolean): DiffItem {
  const lines = node.data.code.split("\n");
  const marker = isRoot ? `// CHANGE: ${prompt}` : `// REVIEW: ${root.data.label} contract changes — "${prompt}"`;
  const identifiers = isRoot ? tokenize(prompt) : exportedIdentifiers(root);

  let flagged = 0;
  const annotated = lines.map((line) => {
    const hits = isRoot
      ? identifiers.some((t) => line.toLowerCase().includes(t))
      : identifiers.some((id) => new RegExp(`\\b${id}\\b`).test(line));
    if (!hits || line.trim().startsWith("//") || line.trim() === "") return line;
    flagged++;
    return `${line} // ⚠ affected`;
  });

  const lastImport = annotated.reduce((acc, line, i) => (/^\s*(import|from)\b/.test(line) ? i : acc), -1);
  annotated.splice(lastImport + 1, 0, ...(lastImport >= 0 ? ["", marker] : [marker]));

  return {
    nodeId: node.id,
    filePath: node.data.filePath,
    before: node.data.code,
    after: annotated.join("\n"),
    rationale:
      flagged > 0
        ? `Heuristic: ${flagged} line(s) reference ${isRoot ? "terms from the change request" : `exports of ${root.data.label}`}.`
        : `Heuristic: no direct references found; review the call path through ${root.data.label}.`,
  };
}

export function analyzeImpactLocally(
  graph: ArchitectureGraph,
  prompt: string,
  selectedNodeId: string | null,
): ImpactAnalysisResult {
  const trimmed = prompt.trim();
  if (!trimmed) throw new Error("Describe the change you want to simulate.");

  const scenario = matchScenario(trimmed, graph.scenarios);
  const rootNodeId = scenario?.rootNodeId ?? resolveRootNode(trimmed, graph, selectedNodeId);
  const root = nodeById(graph.nodes, rootNodeId);
  if (!root) throw new ImpactRootNotFoundError(trimmed);

  const depths = collectDependents(rootNodeId, graph.edges);
  const impacts: NodeImpact[] = Object.entries(depths).map(([nodeId, depth]) => ({
    nodeId,
    depth,
    severity: severityForDepth(depth),
    reason: reasonForDepth(depth, root.data.label),
  }));

  for (const extra of scenario?.extraImpacts ?? []) {
    if (extra.nodeId in depths || !nodeById(graph.nodes, extra.nodeId)) continue;
    impacts.push({ nodeId: extra.nodeId, depth: 1, severity: "impacted", reason: extra.reason });
  }
  impacts.sort((a, b) => a.depth - b.depth);

  const diffs: DiffItem[] = scenario
    ? scenario.diffs.flatMap((d) => {
        const node = nodeById(graph.nodes, d.nodeId);
        return node ? [{ nodeId: d.nodeId, filePath: node.data.filePath, before: node.data.code, after: d.after, rationale: d.rationale }] : [];
      })
    : impacts.flatMap((impact) => {
        const node = nodeById(graph.nodes, impact.nodeId);
        return node ? [heuristicDiff(node, root, trimmed, impact.depth === 0)] : [];
      });

  const brokenCount = impacts.filter((i) => i.severity === "broken").length;
  return {
    prompt: trimmed,
    rootNodeId,
    summary:
      scenario?.summary ??
      `"${root.data.label}" is the origin. ${brokenCount} component(s) consume it directly and ${impacts.length - brokenCount - 1} more are reached transitively. Edits below are heuristic markers — run with Claude for concrete code changes.`,
    riskScore: computeRiskScore(impacts, graph.nodes.length),
    impacts,
    diffs,
    engine: "local",
    scenarioId: scenario?.id,
  };
}

import "server-only";
import { collectDependents, layoutByKind, nodeById } from "@/lib/graph";
import { computeRiskScore } from "@/lib/engines/localImpact";
import { selectGraphFiles, truncateCode } from "@/lib/engines/heuristicGraph";
import { generateStructured } from "@/lib/server/claude";
import { ClaudeImpactSchema, ClaudeIngestSchema, ClaudeScaffoldSchema, ClaudeStorySchema } from "@/lib/server/schemas";
import type {
  ArchitectureGraph,
  ArchNode,
  DependencyEdge,
  ImpactAnalysisResult,
  NodeImpact,
  ScaffoldResult,
  SourceFile,
  StoryNarrative,
} from "@/lib/types";

/** Keeps a single request comfortably inside the context window with room for output. */
const MAX_INGEST_SOURCE_CHARS = 600_000;
const RISK_SCORE_MAX = 100;

function serializeGraph(graph: ArchitectureGraph, includeCode: boolean): string {
  const nodes = graph.nodes.map((n) => {
    const head = `<component id="${n.id}" kind="${n.data.kind}" path="${n.data.filePath}"${n.data.isDraft ? ' draft="true"' : ""}>\n` +
      `label: ${n.data.label}\ndescription: ${n.data.description}\nexports: ${n.data.exports.join(", ") || "-"}`;
    return includeCode ? `${head}\n<code>\n${n.data.code}\n</code>\n</component>` : `${head}\n</component>`;
  });
  const edges = graph.edges.map((e) => `${e.source} -> ${e.target} (${e.relation}${e.label ? `: ${e.label}` : ""})${e.isDraft ? " [new]" : ""}`);
  return `<architecture name="${graph.name}">\n${nodes.join("\n")}\n<dependencies note="source depends on target">\n${edges.join("\n")}\n</dependencies>\n</architecture>`;
}

const SHARED_RULES =
  "Component IDs in your answer must be copied exactly from the input. Code you write must be complete files, not fragments, and must match the conventions already used in the codebase. Do not invent components that are not in the input.";

export async function analyzeImpactWithClaude(
  graph: ArchitectureGraph,
  prompt: string,
  selectedNodeId: string | null,
): Promise<ImpactAnalysisResult> {
  const result = await generateStructured({
    schema: ClaudeImpactSchema,
    effort: "high",
    system: `You are a principal engineer performing refactoring impact analysis on a dependency graph. Identify the component where the requested change originates, every component that must change or will break as a consequence (including non-obvious couplings such as serialized payloads, cache contents and token claims), and write the concrete updated code for each affected file. Severity: "modified" = origin, "broken" = will fail to compile or misbehave without edits, "impacted" = needs review or a smaller edit. ${SHARED_RULES}`,
    prompt: `${serializeGraph(graph, true)}\n\n<selected_component>${selectedNodeId ?? "none"}</selected_component>\n<change_request>${prompt}</change_request>`,
  });

  const rootNodeId = nodeById(graph.nodes, result.rootNodeId) ? result.rootNodeId : selectedNodeId;
  if (!rootNodeId) throw new Error("Claude did not identify a valid origin component.");

  const depths = collectDependents(rootNodeId, graph.edges);
  const seen = new Set<string>();
  const impacts: NodeImpact[] = result.impacts
    .filter((i) => nodeById(graph.nodes, i.nodeId) && !seen.has(i.nodeId) && seen.add(i.nodeId))
    .map((i) => ({ ...i, severity: i.nodeId === rootNodeId ? "modified" : i.severity, depth: depths[i.nodeId] ?? 1 }));
  if (!seen.has(rootNodeId)) impacts.unshift({ nodeId: rootNodeId, severity: "modified", depth: 0, reason: "Origin of the change." });
  impacts.sort((a, b) => a.depth - b.depth);

  return {
    prompt,
    rootNodeId,
    summary: result.summary,
    riskScore: Number.isFinite(result.riskScore)
      ? Math.max(0, Math.min(RISK_SCORE_MAX, Math.round(result.riskScore)))
      : computeRiskScore(impacts, graph.nodes.length),
    impacts,
    diffs: result.diffs.flatMap((d) => {
      const node = nodeById(graph.nodes, d.nodeId);
      return node ? [{ nodeId: d.nodeId, filePath: node.data.filePath, before: node.data.code, after: d.after, rationale: d.rationale }] : [];
    }),
    engine: "claude",
  };
}

export async function narrateStoryWithClaude(graph: ArchitectureGraph): Promise<StoryNarrative> {
  if (graph.commits.length === 0) throw new Error("This repository has no commit history to narrate.");
  const label = (id: string) => nodeById(graph.nodes, id)?.data.label ?? id;
  const history = graph.commits
    .map((c) => `<commit hash="${c.hash}" date="${c.date}" author="${c.author}">\nmessage: ${c.message}\nadded: ${c.addedNodeIds.map(label).join(", ") || "-"}\nmodified: ${c.modifiedNodeIds.map(label).join(", ") || "-"}\n</commit>`)
    .join("\n");

  const result = await generateStructured({
    schema: ClaudeStorySchema,
    effort: "medium",
    system:
      "You are a software archaeologist. Explain how this architecture evolved as a short narrative: for each commit, one titled phase that says what structurally changed and the most plausible engineering reason, and flag couplings or regressions a future maintainer should know. Ground every claim in the commit messages and component changes provided; say when a motive is inferred. Return one phase per commit, using the given hashes.",
    prompt: `${serializeGraph(graph, false)}\n\n<history order="oldest first">\n${history}\n</history>`,
  });

  const known = new Set(graph.commits.map((c) => c.hash));
  return { overview: result.overview, phases: result.phases.filter((p) => known.has(p.hash)), engine: "claude" };
}

export async function scaffoldWithClaude(graph: ArchitectureGraph): Promise<ScaffoldResult> {
  const result = await generateStructured({
    schema: ClaudeScaffoldSchema,
    effort: "high",
    system: `You generate production-quality scaffolding for new components drawn on an architecture diagram. Components marked draft="true" do not exist yet: write one complete file for each at its given path. Dependencies marked [new] must be wired: edit every existing (non-draft) source file of a [new] dependency so it actually uses the new target. Handle errors explicitly and keep each file focused. ${SHARED_RULES}`,
    prompt: serializeGraph(graph, true),
  });

  const drafts = new Set(graph.nodes.filter((n) => n.data.isDraft).map((n) => n.id));
  return {
    summary: result.summary,
    files: result.files.filter((f) => drafts.has(f.nodeId)),
    diffs: result.edits.flatMap((e) => {
      const node = nodeById(graph.nodes, e.nodeId);
      return node && !drafts.has(e.nodeId)
        ? [{ nodeId: e.nodeId, filePath: node.data.filePath, before: node.data.code, after: e.after, rationale: e.rationale }]
        : [];
    }),
    engine: "claude",
  };
}

/** Pack as many whole files as fit the budget; report exactly what was left out. */
function packSources(files: readonly SourceFile[]): { packed: SourceFile[]; omitted: number } {
  const packed: SourceFile[] = [];
  let budget = MAX_INGEST_SOURCE_CHARS;
  for (const file of files) {
    if (file.content.length > budget) continue;
    packed.push(file);
    budget -= file.content.length;
  }
  return { packed, omitted: files.length - packed.length };
}

export async function ingestWithClaude(name: string, files: readonly SourceFile[]): Promise<ArchitectureGraph> {
  const { selected, warnings } = selectGraphFiles(files);
  const { packed, omitted } = packSources(selected);
  if (omitted > 0) warnings.push(`${omitted} large file(s) were not sent to Claude (context budget); they appear only if referenced.`);

  const result = await generateStructured({
    schema: ClaudeIngestSchema,
    effort: "medium",
    system:
      "You map a codebase into an architecture graph of 4-25 components. A component is an architectural unit (a page, an API route, a service/controller, a datastore or cache) anchored to one primary file. Edges point from the dependent to its dependency. Prefer meaningful units over one-node-per-file; use only file paths that appear in the input.",
    prompt: packed.map((f) => `<file path="${f.path}">\n${f.content}\n</file>`).join("\n"),
  });

  const byPath = new Map(files.map((f) => [f.path, f.content]));
  const nodes: ArchNode[] = result.components
    .filter((c) => byPath.has(c.filePath))
    .map((c) => ({
      id: c.id,
      type: "component",
      position: { x: 0, y: 0 },
      data: {
        label: c.label,
        kind: c.kind,
        filePath: c.filePath,
        description: c.description,
        language: c.filePath.split(".").pop() ?? "text",
        code: truncateCode(byPath.get(c.filePath) ?? ""),
        exports: c.exports,
        imports: [],
        params: c.params,
        keywords: c.keywords,
      },
    }));
  const ids = new Set(nodes.map((n) => n.id));
  const edges: DependencyEdge[] = result.edges
    .filter((e) => ids.has(e.source) && ids.has(e.target) && e.source !== e.target)
    .map((e, i) => ({ id: `e-${i}-${e.source}--${e.target}`, ...e }));

  return {
    id: `import-${name.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-${Date.now().toString(36)}`,
    name,
    description: result.description,
    nodes: layoutByKind(nodes),
    edges,
    commits: [],
    scenarios: [],
    warnings,
  };
}

import "server-only";
import Anthropic from "@anthropic-ai/sdk";
import { betaZodOutputFormat } from "@anthropic-ai/sdk/helpers/beta/zod";
import type * as z from "zod/v4";

export const CLAUDE_MODEL = process.env.CODEARCHITECT_MODEL || "claude-opus-5-5";
const FALLBACK_BETA = "server-side-fallback-2026-07-01";
const MAX_OUTPUT_TOKENS = 16_000;

export type Effort = "low" | "medium" | "high" | "xhigh" | "max";

export class ClaudeUnavailableError extends Error {
  constructor() {
    super("Claude is not configured (set ANTHROPIC_API_KEY, or CODEARCHITECT_ENGINE=claude with an `ant auth login` profile).");
    this.name = "ClaudeUnavailableError";
  }
}

export class ClaudeResponseError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ClaudeResponseError";
  }
}

/**
 * `CODEARCHITECT_ENGINE`: "local" forces the deterministic engine, "claude"
 * forces Claude (credentials may come from an `ant` profile), "auto" (default)
 * uses Claude only when an API key/token is present in the environment.
 */
export function isClaudeEnabled(): boolean {
  const mode = (process.env.CODEARCHITECT_ENGINE ?? "auto").toLowerCase();
  if (mode === "local") return false;
  if (mode === "claude") return true;
  return Boolean(process.env.ANTHROPIC_API_KEY || process.env.ANTHROPIC_AUTH_TOKEN);
}

let client: Anthropic | null = null;
function getClient(): Anthropic {
  if (!isClaudeEnabled()) throw new ClaudeUnavailableError();
  client ??= new Anthropic();
  return client;
}

/**
 * One structured-output call. The response is schema-validated by the SDK;
 * callers still validate cross-references (node IDs) against their graph.
 */
export async function generateStructured<Schema extends z.ZodType>(options: {
  schema: Schema;
  system: string;
  prompt: string;
  effort: Effort;
}): Promise<z.infer<Schema>> {
  const response = await getClient().beta.messages.parse({
    model: CLAUDE_MODEL,
    max_tokens: MAX_OUTPUT_TOKENS,
    betas: [FALLBACK_BETA],
    fallbacks: "default",
    system: options.system,
    output_config: { effort: options.effort, format: betaZodOutputFormat(options.schema) },
    messages: [{ role: "user", content: options.prompt }],
  });

  if (response.stop_reason === "refusal") {
    const category = response.stop_details?.category ?? "unspecified";
    throw new ClaudeResponseError(`Claude declined this request (category: ${category}).`);
  }
  if (response.stop_reason === "max_tokens") {
    throw new ClaudeResponseError("Claude's answer exceeded the output limit; try a smaller scope.");
  }
  if (!response.parsed_output) {
    throw new ClaudeResponseError("Claude returned output that did not match the expected schema.");
  }
  return response.parsed_output as z.infer<Schema>;
}

/** Map SDK errors to a short, user-safe message (never echo keys or raw payloads). */
export function describeClaudeError(error: unknown): string {
  if (error instanceof ClaudeUnavailableError || error instanceof ClaudeResponseError) return error.message;
  if (error instanceof Anthropic.AuthenticationError) return "Claude rejected the configured credentials.";
  if (error instanceof Anthropic.RateLimitError) return "Claude rate limit reached; retry shortly.";
  if (error instanceof Anthropic.BadRequestError) return `Claude rejected the request: ${error.message}`;
  if (error instanceof Anthropic.APIConnectionError) return "Could not reach the Claude API.";
  if (error instanceof Anthropic.APIError) return `Claude API error (${error.status ?? "unknown"}).`;
  return error instanceof Error ? error.message : "Unknown error while calling Claude.";
}
